const WORLDS = [
 { id: "itgw1", n: 1, title: "Was ist die Cloud?", sub: "Definition, NIST, Deployment-Modelle", boss: { id: "boss-itgw1", title: "Kapiteltest: Cloud-Modelle", topics: ["itg-def", "itg-nist", "itg-deploy"] }, lessons: [
  { id: "itg1-1", title: "Horseless Carriage & Definition", topic: "itg-def", min: 10, xp: 0, blocks: [
    { t: "lead", html: "„Horseless carriage“ – so hieß das Auto, bevor man verstand, was es wirklich ist. Mit der Cloud passiert gerade dasselbe: Wir beschreiben sie oft noch über das, was ihr fehlt („kein eigener Server“)." },
    { t: "text", h: "Horseless Carriage Syndrome", levels: {
      simple: "Neue Technik wird anfangs mit alter Technik verglichen und unterschätzt. Daimler glaubte, es werde nie mehr als 1 Million Autos geben – heute sind es über 1,3 Milliarden.",
      normal: "Der Begriff <b>Horseless Carriage</b> (pferdelose Kutsche) zeigt, wie man eine neue Technologie über das definiert, was ihr im Vergleich zur alten <i>fehlt</i> (vgl. „wireless phone“). Gottlieb Daimler schätzte den Markt auf höchstens <b>1 Million Autos</b> – wegen hoher Kosten und zu weniger fähiger Chauffeure. In den 1920ern gab es bereits 8 Millionen, heute über <b>1,3 Milliarden</b>. Was die Pioniere übersahen: Drastisch sinkende <b>Kosten und Komplexität</b> sowie steigende Bedeutung im Alltag haben die alten Grenzen überrollt.<br><br>Die IT erlebt laut „The Economics of the Cloud“ (Microsoft) einen ähnlichen Umbruch: den Wechsel von <b>Client/Server (on-premises)</b> zur <b>Cloud</b>. Die Cloud verspricht nicht nur billigere, sondern auch <b>schnellere, einfachere, flexiblere und effektivere</b> IT.",
      technical: "Die Analogie ist ökonomisch gemeint: Nicht die Technik allein, sondern Kosten- und Komplexitätsreduktion treiben Disruptionen (siehe Kapitel Cloud Economics). Die Folien stützen sich auf Microsoft „The Economics of the Cloud“ (2010) und den Berkeley-Report „Above the Clouds“ (Armbrust et al., UCB/EECS-2009-28)." } },
    { t: "text", h: "Definition", levels: {
      simple: "Cloud Computing = IT-Leistungen (Rechnen, Netz, Speicher, Analyse) übers Internet beziehen statt selbst betreiben.",
      normal: "<b>Cloud Computing</b> ist die Bereitstellung von Computing-Diensten <b>über das Internet</b> und ermöglicht <b>schnellere Innovation, flexible Ressourcen und Economies of Scale</b>. Typische Dienstkategorien: <b>Compute, Networking, Storage, Analytics</b>.",
      technical: "Die formale, prüfungsrelevante Definition liefert NIST SP 800-145 (Mell/Grance 2011): ein Modell aus <b>5 Essential Characteristics</b>, <b>3 Service Models</b> und <b>4 Deployment Models</b>. Serverless und Multi-Cloud sind spätere Ergänzungen, die nicht in NIST stehen." } },
    { t: "keys", items: ["Gliederung der Einheit: Cloud-Modelle → Bare Metal bis Serverless → Shared Responsibility & Benefits (inkl. SLAs) → Cloud Economics → Markt, Risiken & digitale Souveränität", "Cloud = Computing-Dienste über das Internet: Compute, Networking, Storage, Analytics", "Treiber des Wandels ist vor allem die <b>Ökonomie</b>, nicht nur die Technik", "NIST-Modell: 5 Merkmale · 3 Service-Modelle · 4 Deployment-Modelle"] },
    { t: "check", q: "Was beschreibt das „Horseless Carriage Syndrome“?", opts: ["Neue Technologien werden über das definiert, was ihnen im Vergleich zur alten fehlt, und dadurch unterschätzt", "Alte Technologien verschwinden immer sofort", "Autos waren anfangs teurer als Kutschen", "Cloud-Anbieter verwenden veraltete Hardware"], a: 0, why: "Beispiele: horseless carriage, wireless phone. Daimler unterschätzte den Automarkt massiv." }
  ]},
  { id: "itg1-2", title: "NIST: Die 5 Essential Characteristics", topic: "itg-nist", min: 12, xp: 0, blocks: [
    { t: "lead", html: "NIST SP 800-145 definiert Cloud Computing über fünf Merkmale – fehlt eines, ist es streng genommen keine Cloud." },
    { t: "html", html: "<table class='dt'><tr><th>Merkmal</th><th>Bedeutung</th><th>Beispiel</th></tr><tr><td><b>On-demand self-service</b></td><td>Kunde stellt Ressourcen selbst und automatisch bereit – ohne menschliche Interaktion mit dem Anbieter</td><td>VM im Azure-Portal anlegen, ohne Ticket</td></tr><tr><td><b>Broad network access</b></td><td>Zugriff über das Netz mit Standardmechanismen, von heterogenen Thin/Thick Clients</td><td>Handy, Tablet, Laptop, Workstation</td></tr><tr><td><b>Resource pooling</b></td><td>Ressourcen des Anbieters werden in einem <b>Multi-Tenant</b>-Modell gebündelt und dynamisch zugeteilt; Ortsunabhängigkeit (Ort nur grob wählbar: Land, Region, Rechenzentrum)</td><td>Viele Kunden teilen sich physische Hosts</td></tr><tr><td><b>Rapid elasticity</b></td><td>Ressourcen werden elastisch, teils automatisch, hinzugefügt und freigegeben; wirken für den Kunden unbegrenzt</td><td>Autoscaling am Black Friday</td></tr><tr><td><b>Measured service</b></td><td>Verbrauch wird gemessen (Metering), überwacht, gesteuert und berichtet – Transparenz für Anbieter und Kunden</td><td>Abrechnung nach Speicher, CPU-Zeit, Bandbreite, aktiven Usern</td></tr></table>" },
    { t: "text", h: "Die Merkmale genauer", levels: {
      simple: "Selbst bestellen, von überall erreichbar, geteilte Ressourcen, schnell wachsen und schrumpfen, nach Verbrauch messen.",
      normal: "<b>On-demand self-service</b>: Server-Zeit oder Netzwerkspeicher werden einseitig („unilaterally“) und automatisch bezogen. <b>Broad network access</b>: Standardprotokolle, beliebige Endgeräte. <b>Resource pooling</b>: physische und virtuelle Ressourcen (Storage, Processing, Memory, Bandbreite) dienen vielen Kunden gleichzeitig; der Kunde kennt den exakten Standort meist nicht, kann ihn aber auf höherer Ebene (Land, Bundesstaat, Rechenzentrum) festlegen. <b>Rapid elasticity</b>: Skalierung nach außen und innen (scale out / scale in) entsprechend der Nachfrage. <b>Measured service</b>: automatische Kontrolle und Optimierung durch Metering – Basis für nutzungsbasierte Abrechnung.",
      technical: "Abgrenzung: Elastizität (automatisch, kurzfristig, in beide Richtungen) ist mehr als bloße Skalierbarkeit. Resource pooling + Multi-Tenancy ist die technische Basis für die Economies of Scale und die Glättung von Lastspitzen über viele Kunden. Measured service ermöglicht das Consumption-based Model (OpEx)." } },
    { t: "widget", w: "pairs", topic: "itg-nist", title: "Merkmal ↔ Beschreibung", pairs: [["On-demand self-service", "Bereitstellung ohne menschliche Interaktion mit dem Anbieter"], ["Broad network access", "Zugriff über Standardmechanismen von beliebigen Endgeräten"], ["Resource pooling", "Multi-Tenant-Modell mit dynamischer Zuteilung"], ["Rapid elasticity", "Ressourcen wachsen und schrumpfen mit der Nachfrage"], ["Measured service", "Verbrauch wird gemessen und transparent berichtet"]] },
    { t: "warnbox", html: "Prüfungsfalle: „Pay-as-you-go“ oder „Internet“ sind <b>keine</b> eigenen NIST-Merkmale. Die nutzungsbasierte Abrechnung folgt aus <b>Measured service</b>, der Netzzugang heißt <b>Broad network access</b>." },
    { t: "check", q: "Ein Kunde kann den Standort seiner Daten nur auf Ebene „Region Westeuropa“ wählen, nicht aber den konkreten Server. Welches NIST-Merkmal beschreibt das?", opts: ["Measured service", "Resource pooling", "Rapid elasticity", "Broad network access"], a: 1, why: "Resource pooling beinhaltet eine „sense of location independence“: Ort nur auf höherer Abstraktionsebene wählbar." }
  ]},
  { id: "itg1-3", title: "Deployment-Modelle & Multi-Cloud", topic: "itg-deploy", min: 12, xp: 0, blocks: [
    { t: "lead", html: "Wem gehört die Cloud und wer darf sie nutzen? NIST unterscheidet vier Deployment-Modelle – Multi-Cloud kam später als gelebte Praxis dazu." },
    { t: "html", html: "<table class='dt'><tr><th>Modell</th><th>Nutzung</th><th>Betrieb / Ort</th></tr><tr><td><b>Private Cloud</b></td><td>exklusiv für <b>eine Organisation</b> (mit mehreren Konsumenten, z. B. Geschäftsbereichen)</td><td>Organisation, Dritte oder beide; on oder off premises</td></tr><tr><td><b>Community Cloud</b></td><td>exklusiv für eine <b>Gemeinschaft</b> von Organisationen mit gemeinsamen Anliegen (Mission, Security, Policy, Compliance)</td><td>eine/mehrere der Organisationen, Dritte; on oder off premises</td></tr><tr><td><b>Public Cloud</b></td><td>offen für die <b>Allgemeinheit</b></td><td>Unternehmen, Uni, Behörde; liegt beim <b>Cloud-Anbieter</b></td></tr><tr><td><b>Hybrid Cloud</b></td><td><b>Komposition</b> aus zwei oder mehr eigenständigen Clouds (private, community, public)</td><td>verbunden durch standardisierte oder proprietäre Technik, die Daten- und Anwendungsportabilität ermöglicht (z. B. <b>Cloud Bursting</b>)</td></tr></table>" },
    { t: "text", h: "Vergleich und Multi-Cloud", levels: {
      simple: "Public: mieten, nur zahlen was man nutzt. Private: selbst kaufen und volle Kontrolle. Hybrid: beides kombiniert. Multi-Cloud: mehrere Public-Cloud-Anbieter gleichzeitig.",
      normal: "<b>Public Cloud</b>: keine Investitionen (CapEx) zum Hochskalieren, Anwendungen schnell bereit- und abbaubar, Bezahlung nur für Genutztes. <b>Private Cloud</b>: Hardware muss gekauft und gewartet werden, volle Kontrolle über Ressourcen und Sicherheit, Organisation verantwortet Wartung und Updates. <b>Hybrid Cloud</b>: größte Flexibilität, die Organisation entscheidet, wo Anwendungen laufen, und behält Kontrolle über Security, Compliance und rechtliche Anforderungen.<br><br><b>Multi-Cloud</b> = Dienste von <b>zwei oder mehr Public-Cloud-Anbietern</b> (z. B. Azure + AWS). Nicht Teil der NIST-Definition (2011), aber Alltag. <b>Motive</b>: Vendor Lock-in vermeiden, Best-of-Breed-Services, Resilienz, Regulatorik, Verhandlungsmacht. <b>Herausforderungen</b>: unterschiedliche APIs und Tools, Skills für mehrere Plattformen, Datentransfer-(Egress-)Kosten, schwierigere Governance und Security.",
      technical: "<b>Hybrid ≠ Multi-Cloud</b>: Hybrid kombiniert on-premises/Private Cloud mit Public Cloud; Multi-Cloud kombiniert mehrere Public Clouds – in der Praxis oft beides zugleich. Gartner erwartet, dass bis 2027 90 % der Organisationen einen Hybrid-Ansatz verfolgen. Azure-Beispiel: <b>Azure Arc</b> verwaltet Server, Kubernetes-Cluster und Datendienste on-premises und in anderen Clouds über die Azure-Steuerungsebene. Hinweise der Folie: Mit „Cloud“ ist meist stillschweigend Public Cloud gemeint; Lock-in-Sorgen werden oft mit Private-Cloud-Ansätzen beantwortet – auch wenn das ökonomisch nicht immer sinnvoll ist." } },
    { t: "widget", w: "sorter", topic: "itg-deploy", title: "Welches Deployment-Modell?", cats: [{ k: "pub", label: "Public" }, { k: "priv", label: "Private" }, { k: "hyb", label: "Hybrid" }, { k: "multi", label: "Multi-Cloud" }, { k: "comm", label: "Community" }],
      items: [{ t: "Keine Investitionen nötig, um hochzuskalieren", a: "pub", why: "" }, { t: "Hardware muss für Start und Wartung gekauft werden", a: "priv", why: "" }, { t: "Lastspitzen werden per Cloud Bursting aus dem eigenen RZ in die Public Cloud ausgelagert", a: "hyb", why: "" }, { t: "Webshop auf Azure, Analytics auf AWS", a: "multi", why: "Zwei Public-Cloud-Anbieter." }, { t: "Gemeinsame Cloud mehrerer Krankenhäuser mit gleichen Compliance-Anforderungen", a: "comm", why: "" }, { t: "Volle Kontrolle über Ressourcen und Sicherheit, eigene Wartung", a: "priv", why: "" }, { t: "Organisation entscheidet je Anwendung, wo sie läuft (on-prem oder Public Cloud)", a: "hyb", why: "" }, { t: "Liegt immer in den Räumen des Cloud-Anbieters", a: "pub", why: "" }] },
    { t: "check", q: "Was unterscheidet Multi-Cloud von Hybrid Cloud?", opts: ["Multi-Cloud nutzt mehrere Public-Cloud-Anbieter, Hybrid kombiniert on-premises/Private mit Public Cloud", "Es gibt keinen Unterschied", "Hybrid ist Teil von Multi-Cloud und nur für Behörden", "Multi-Cloud ist eines der vier NIST-Modelle"], a: 0, why: "Multi-Cloud ist nicht in NIST (2011) enthalten; Hybrid schon." },
    { t: "check", q: "Laut NIST kann eine Private Cloud …", opts: ["nur im eigenen Rechenzentrum stehen", "auch von Dritten betrieben werden und off premises liegen", "von der Allgemeinheit genutzt werden", "nur aus Containern bestehen"], a: 1, why: "Entscheidend ist die exklusive Nutzung durch eine Organisation, nicht Ort oder Betreiber." }
  ]}
 ]},
 { id: "itgw2", n: 2, title: "Vom Bare Metal zu Serverless", sub: "Webshop-Beispiel: Server, VMs, Container, Functions", boss: { id: "boss-itgw2", title: "Kapiteltest: Bare Metal bis Serverless", topics: ["itg-virt", "itg-faas"] }, lessons: [
  { id: "itg2-1", title: "Dedicated Server, VMs und Container", topic: "itg-virt", min: 15, xp: 0, blocks: [
    { t: "lead", html: "Ein Online-Shop am Abend unter Volllast, in der Nacht im Leerlauf: An diesem Beispiel zeigt die Folie, warum die IT von dedizierten Servern über VMs zu Containern gewandert ist." },
    { t: "html", html: "<table class='dt'><tr><th>Stufe (Kratzke 2018)</th><th>Idee</th><th>Problem, das gelöst wird</th></tr><tr><td>1 · Dedicated Server</td><td>Jede Anwendung (A, B) auf eigenem physischen Server</td><td>– (Ausgangslage: überdimensioniert, schlecht ausgelastet)</td></tr><tr><td>2 · Virtualisierung</td><td>Anwendungen in VMs auf einem Bare-Metal-Server</td><td>höhere Anwendungsdichte; aber VM-Images (Deployment Units) sind sehr groß</td></tr><tr><td>3 · Containerization / Microservices</td><td>mehrere Container teilen sich das Betriebssystem einer VM</td><td>kleinere Deployment Units, schnellerer Start, höhere Dichte je VM</td></tr><tr><td>4 · Serverless / FaaS</td><td>FaaS-Runtime teilt sich den Host per <b>Time-Sharing</b></td><td>Ressourcen nur bei eingehenden Requests; erfordert serverlosen Architekturstil</td></tr></table>" },
    { t: "text", h: "Probleme im klassischen Rechenzentrum (Webshop 1–3)", levels: {
      simple: "Der Server läuft immer, auch wenn nachts niemand einkauft. Er muss für die Spitze gekauft werden, und wenn er kaputtgeht, ist Wiederherstellung mühsam.",
      normal: "<b>Leerlauf kostet</b>: Abends Volllast, nachts passiert nichts – der Server läuft trotzdem und verbraucht Strom → sehr schlechte Auslastung, hohe Kosten.<br><b>Überdimensionierung</b>: Server müssen für die <b>Spitzenlast</b> ausgelegt werden, also bleibt der Großteil der Kapazität ungenutzt – man zahlt für Leistung, die man nicht braucht.<br><b>Abhängigkeit & schwierige Wiederherstellung</b>: Das Betriebssystem ist eng an die Hardware gebunden, ein Klon auf anderem Server ist schwierig, Backup und Recovery sind kompliziert – das System ist unflexibel und fehleranfällig.",
      technical: "Diese drei Probleme tauchen später ökonomisch wieder auf: Leerlauf und Überdimensionierung sind genau die Lücke zwischen Peak (p) und Average (a) in der p/a-Regel; die Hardwarebindung löst die Virtualisierung durch Abstraktion (Hypervisor)." } },
    { t: "text", h: "Virtuelle Maschinen und Container", levels: {
      simple: "VMs teilen einen echten Server in mehrere virtuelle. Container sind noch leichter: Sie packen nur die App und ihre Abhängigkeiten ein, nicht ein ganzes Betriebssystem.",
      normal: "<b>VMs – Vorteile</b>: <b>bessere Auslastung</b> (mehrere VMs teilen sich einen Bare-Metal-Server, Kosten verteilen sich), <b>Hardwareunabhängigkeit</b> (VMs lassen sich leicht auf andere Server verschieben), <b>einfache Prozesse</b> (Backup und Restore leicht einzurichten), <b>Standardisierung</b> über <b>Golden Images</b> (reproduzierbare Standardumgebungen).<br><br><b>Container</b>: VMs haben noch Overhead, weil jede ein <b>komplettes Betriebssystem</b> bootet. Container packen nur <b>Anwendung + Abhängigkeiten</b> und brauchen nur eine <b>Container-Runtime</b> auf dem Bare-Metal-Server oder in einer VM. Vorteile: <b>Ressourceneffizienz</b> (nutzen das Betriebssystem des Hosts), <b>Portabilität</b>, <b>schnelleres Deployment</b> (rollout, update, scale), <b>beschleunigte Entwicklung</b> (gleiche Images auf jedem Entwicklerrechner → konsistente Umgebung).",
      technical: "VMs virtualisieren Hardware (Hypervisor, eigener Kernel je VM, starke Isolation). Container virtualisieren auf Betriebssystemebene: Sie teilen sich den Kernel des Hosts (Linux: Namespaces + cgroups), daher Start in Sekunden und kleine Images – aber schwächere Isolation als VMs. Deshalb laufen Container in der Public Cloud meist <i>innerhalb</i> von VMs. Fazit der Folie: Containers sind de-facto-Standard moderner Softwareentwicklung; Bare Metal bleibt das physische Fundament." } },
    { t: "widget", w: "sorter", topic: "itg-virt", title: "VM oder Container?", cats: [{ k: "vm", label: "Virtuelle Maschine" }, { k: "ct", label: "Container" }],
      items: [{ t: "Bootet ein vollständiges eigenes Betriebssystem", a: "vm", why: "" }, { t: "Packt nur Anwendung und Abhängigkeiten", a: "ct", why: "" }, { t: "Nutzt das Betriebssystem (den Kernel) des Hosts mit", a: "ct", why: "" }, { t: "Standardisierung über „Golden Images“ (laut Folie)", a: "vm", why: "" }, { t: "Benötigt nur eine Runtime/Engine auf Server oder VM", a: "ct", why: "" }, { t: "Großes Image als Deployment Unit", a: "vm", why: "Laut Kratzke: VM-Images sind sehr groß." }, { t: "Gilt als de-facto-Standard moderner Softwareentwicklung", a: "ct", why: "" }] },
    { t: "check", q: "Warum sind Container ressourcensparender als VMs?", opts: ["Sie haben mehr RAM", "Sie teilen sich das Betriebssystem des Hosts statt jeweils ein eigenes zu booten", "Sie laufen nur in der Public Cloud", "Sie benötigen keine Hardware"], a: 1, why: "Kein eigenes OS je Instanz → weniger Overhead, schnellerer Start." },
    { t: "check", q: "Welches Problem des Webshops lösen VMs direkt?", opts: ["Kalte Starts", "Die enge Bindung des Betriebssystems an die Hardware (schwierige Wiederherstellung)", "Egress-Kosten", "Den CLOUD Act"], a: 1, why: "Hardwareunabhängigkeit: VMs lassen sich verschieben, Backup/Restore wird einfach." }
  ]},
  { id: "itg2-2", title: "Serverless / Function as a Service", topic: "itg-faas", min: 12, xp: 0, blocks: [
    { t: "lead", html: "Serverless heißt: nur zahlen, wenn etwas passiert. Nachts, wenn niemand bestellt, läuft nichts – und es wird nichts verrechnet." },
    { t: "html", html: "<table class='dt'><tr><th>Event (Trigger)</th><th>Azure Function</th><th>Ergebnis</th></tr><tr><td>Neue Bestellung (HTTP-Request)</td><td><code>SendConfirmation</code></td><td>Bestätigungs-E-Mail an Kunden</td></tr><tr><td>Produktbild hochgeladen (Blob Storage)</td><td><code>ResizeImage</code></td><td>Thumbnails für den Shop</td></tr><tr><td>Jede Nacht 02:00 (Timer)</td><td><code>DailySalesReport</code></td><td>Bericht an das Management</td></tr></table>" },
    { t: "text", h: "Wie Serverless funktioniert", levels: {
      simple: "Man schreibt nur kleine Funktionen. Die laufen automatisch, wenn etwas passiert (Bestellung, Upload, Uhrzeit). Server verwaltet der Anbieter.",
      normal: "<b>Serverless / FaaS</b> ist die <b>nächste Abstraktionsstufe nach PaaS</b>: Man deployt nur <b>Code (Functions) oder Container</b>; Server, Betriebssystem, Runtime und Skalierung übernimmt der Anbieter.<ul><li><b>Event-driven</b>: Code läuft, wenn er ausgelöst wird – HTTP-Request, Datei-Upload, Queue-Nachricht, Timer.</li><li><b>Skaliert automatisch</b> – inklusive <b>Scale to Zero</b> ohne Last; am Black Friday startet die Plattform so viele Instanzen wie nötig.</li><li><b>Abrechnung</b> pro Ausführung und Laufzeit (z. B. <b>GB-Sekunden</b>), nicht pro bereitgestelltem Server.</li><li><b>Azure-Beispiele</b>: Azure Functions, Azure Container Apps, Azure Logic Apps.</li></ul><b>Trade-offs</b>: <b>Cold Starts</b>, Ausführungszeitlimits, starke Plattformbindung (<b>Lock-in</b>), schwierigeres Debugging und Testen. Darum bleibt der Kern-Shop meist in Containern oder PaaS – Functions <b>ergänzen</b> ihn.",
      technical: "Ökonomischer Bezug: Serverless ist ideal für <b>periodische und unvorhersehbare Workloads</b> mit hohem p/a-Verhältnis, weil Leerlauf nichts kostet. Ein Cold Start entsteht, wenn nach Scale to Zero erst eine neue Instanz (Runtime, Code, Abhängigkeiten) hochgefahren werden muss. Laut Kratzke teilt die FaaS-Runtime den Host per Time-Sharing; dafür muss die Anwendung einem serverlosen Architekturstil folgen (kurzlebige, zustandslose Funktionen)." } },
    { t: "keys", items: ["Bare Metal = physisches Fundament", "VMs = bessere Auslastung und Flexibilität", "Container = effizienteste Methode, Anwendungen zu betreiben; de-facto-Standard", "Serverless Functions = Ergänzung für event-getriebene Aufgaben und unvorhersehbare Lastspitzen", "Die Technologien schließen sich <b>nicht</b> gegenseitig aus – jede hat ihren Zweck"] },
    { t: "widget", w: "gapfill", topic: "itg-faas", title: "Serverless-Begriffe", items: [{ s: "Wenn keine Last anliegt, skaliert eine Function auf null herunter: Scale to ___.", a: ["zero", "null", "0"] }, { s: "Die Verzögerung beim ersten Aufruf nach Leerlauf heißt Cold ___.", a: ["start", "starts"] }, { s: "Serverless wird pro Ausführung und Laufzeit abgerechnet, z. B. in GB-___.", a: ["sekunden", "seconds", "sekunde"] }, { s: "Ein Trigger, der jede Nacht um 02:00 auslöst, ist ein ___-Trigger.", a: ["timer", "zeit"] }] },
    { t: "check", q: "Welcher Nachteil gehört typischerweise zu Serverless/FaaS?", opts: ["Man muss Betriebssystem-Patches selbst einspielen", "Cold Starts und starke Plattformbindung", "Abrechnung auch im Leerlauf", "Keine automatische Skalierung"], a: 1, why: "Weitere: Ausführungszeitlimits, schwieriges Debugging/Testen." }
  ]}
 ]},
 { id: "itgw3", n: 3, title: "Service-Modelle & Shared Responsibility", sub: "IaaS, PaaS, SaaS, Benefits, SLAs", boss: { id: "boss-itgw3", title: "Kapiteltest: Service-Modelle & SLAs", topics: ["itg-svc", "itg-shared", "itg-sla"] }, lessons: [
  { id: "itg3-1", title: "Die Service-Schichten: IaaS, PaaS, SaaS", topic: "itg-svc", min: 14, xp: 0, blocks: [
    { t: "lead", html: "Jede Schicht abstrahiert die darunterliegende: vom Rechenzentrum über Infrastruktur und Plattform bis zur fertigen Software." },
    { t: "html", html: "<table class='dt'><tr><th>Schicht</th><th>Zielgruppe</th><th>Kennzeichen</th></tr><tr><td>Layer 4 · <b>SaaS</b></td><td>Kunde, User</td><td>anpassbare Software-Services, XaaS, transparente Updates</td></tr><tr><td>Layer 3 · <b>PaaS</b></td><td>Developer</td><td>APIs, Plattformdienste, Abstraktion der Hardware-Infrastruktur</td></tr><tr><td>Layer 2 · <b>IaaS</b></td><td>Administrator</td><td>Elastizität, virtuelle Ressourcenpools, technische Infrastruktur (VM, Storage, Network)</td></tr><tr><td>Layer 1 · Hardware</td><td>Rechenzentrum</td><td>Server, Netzwerk, Storage</td></tr></table>" },
    { t: "text", h: "IaaS – Infrastructure as a Service", levels: {
      simple: "Man mietet virtuelle Server, Speicher und Netz. Betriebssystem und Apps kümmert man sich selbst darum.",
      normal: "IaaS ist das Modell, das dem Betrieb <b>physischer Server am nächsten</b> kommt. Der Anbieter hält die <b>Hardware</b> aktuell; <b>Betriebssystem-Wartung, Netzwerkkonfiguration und Anwendungsmanagement</b> liegen beim Cloud-Tenant. Beispiel: <b>Cloud-VMs</b> – voll funktionsfähige virtuelle Rechner im Rechenzentrum. Vorteil: <b>schnelle Bereitstellung</b> – eine VM ist erheblich schneller aufgesetzt als ein physischer Server beschafft, installiert und konfiguriert. Kurz: pay-as-you-go-IT-Infrastruktur durch Mieten von Servern, VMs, Storage, Netzwerken und Betriebssystemen.",
      technical: "Azure-Beispiele: Virtual Machines, Managed Disks, Virtual Networks. IaaS bietet maximale Flexibilität für jede selbst erstellte Software, verlangt aber, dass der Kunde mit der operativen Komplexität umgehen kann (Patching, Härtung, Backup, Skalierung)." } },
    { t: "text", h: "PaaS – Platform as a Service", levels: {
      simple: "Man bekommt eine fertige Plattform und lädt nur noch seine App hoch.",
      normal: "PaaS ist eine <b>verwaltete Hosting-Umgebung</b>. Der Anbieter verwaltet die VMs <b>inklusive Betriebssystem</b> und die Netzwerkressourcen; der Kunde <b>deployt seine Anwendung</b> hinein. Umgebung zum Entwickeln, Testen und Ausliefern von Software, ohne sich um die Infrastruktur zu kümmern. Beispiel: <b>Azure App Service</b> – Entwickler laden ihre Webanwendung hoch, ohne sich um Hardware und Software darunter sorgen zu müssen.",
      technical: "Weitere PaaS-Beispiele: Azure SQL Database (managed DB). PaaS ist laut Folie ein Kompromiss: komfortabler Betrieb selbst gebauter Software, aber man muss ressourceneffiziente Architekturen der Plattform befolgen und ein gewisses Maß an Vendor Lock-in akzeptieren." } },
    { t: "text", h: "SaaS – Software as a Service", levels: {
      simple: "Fertige Software im Browser nutzen, z. B. Microsoft 365. Man liefert nur seine Daten.",
      normal: "Der Konsument nutzt die <b>Anwendungen des Anbieters</b>, die auf Cloud-Infrastruktur laufen – über einen Thin Client (z. B. <b>Webbrowser</b>, Web-Mail) oder eine Programmschnittstelle. Der Anbieter verwaltet <b>alle Aspekte</b> (VMs, Netzwerk, Datenspeicher, Anwendungen). Der Konsument kontrolliert weder Netzwerk, Server, Betriebssysteme, Storage noch einzelne Anwendungsfunktionen – höchstens <b>begrenzte benutzerspezifische Einstellungen</b>. Er liefert nur die <b>Daten</b>. Beispiele: <b>Microsoft 365</b>, E-Mail, Kalender, Teams, Salesforce CRM. Abrechnung meist im <b>Abo-Modell</b>.",
      technical: "SaaS verbirgt die Betriebskomplexität fast vollständig, ist aber für Fälle, in denen Nutzer eigene Software schreiben, stark eingeschränkt. Je weiter nach oben (IaaS → PaaS → SaaS), desto größer der ausgelagerte Anteil der Wertschöpfung – und desto größer der Lock-in." } },
    { t: "widget", w: "pairs", topic: "itg-svc", title: "Schicht ↔ Zielgruppe & Beispiel", pairs: [["IaaS", "Administrator · Azure Virtual Machine"], ["PaaS", "Developer · Azure App Service"], ["SaaS", "End-User · Microsoft 365"], ["Serverless / FaaS", "Code per Event · Azure Functions"], ["Hardware (Layer 1)", "Rechenzentrum · Server, Netzwerk, Storage"]] },
    { t: "check", q: "Bei IaaS ist für das Betriebssystem der VM verantwortlich …", opts: ["der Cloud-Anbieter", "der Kunde (Tenant)", "niemand – es gibt kein Betriebssystem", "der Hardwarehersteller"], a: 1, why: "Der Anbieter hält nur die Hardware aktuell; OS, Netzwerkkonfiguration und Anwendungen sind Sache des Kunden." }
  ]},
  { id: "itg3-2", title: "Vergleich, Pizza as a Service & Zuordnungsquiz", topic: "itg-svc", min: 12, xp: 0, blocks: [
    { t: "html", html: "<table class='dt'><tr><th></th><th>IaaS</th><th>PaaS</th><th>SaaS</th></tr><tr><td>Charakter</td><td>flexibelster Cloud-Service</td><td>Fokus auf Anwendungsentwicklung</td><td>gebrauchsfertige Software für End-User</td></tr><tr><td>Wer verwaltet?</td><td>Kunde konfiguriert und verwaltet „Hardware“ (VMs) für seine App</td><td>Plattform-Management macht der Anbieter</td><td>Anbieter fast alles; User zahlt Abo</td></tr><tr><td>Einschätzung</td><td>maximale Flexibilität, aber Kunde muss operative Komplexität beherrschen</td><td>Kompromiss: komfortabler Betrieb, aber ressourceneffiziente Architektur und Lock-in in Kauf nehmen</td><td>verbirgt Betriebskomplexität fast vollständig; stark eingeschränkt für eigene Software</td></tr></table>" },
    { t: "text", h: "Pizza as a Service", levels: {
      simple: "Selbst backen = on-premises. Fertigpizza aufbacken = IaaS. Lieferdienst = PaaS. Restaurant = SaaS.",
      normal: "<b>Homemade (Pizza di Mama)</b>: Teig, Sauce, Belag, Käse, Ofen, Getränke, Tisch – alles selbst → <b>on-premises</b>.<br><b>Take + Bake</b>: fertige Pizza kaufen, nur noch im eigenen Ofen backen, Getränke, Tisch → <b>IaaS</b>.<br><b>Home Delivery</b>: Pizza wird geliefert, man sorgt nur noch für Getränke und Tisch → <b>PaaS</b>.<br><b>Restaurant</b>: Pizza essen mit minimalem Aufwand → <b>SaaS</b>.",
      technical: "Die Analogie zeigt die wandernde Verantwortungsgrenze. Sie ist eine Vereinfachung: Auch im „Restaurant“ (SaaS) bleibt der Gast für bestimmte Dinge verantwortlich – in der Cloud für Daten, Geräte und Identitäten (siehe Shared Responsibility)." } },
    { t: "widget", w: "sorter", topic: "itg-svc", title: "Quiz der Folie: IaaS, PaaS, SaaS oder Serverless?", cats: [{ k: "i", label: "IaaS" }, { k: "p", label: "PaaS" }, { k: "s", label: "SaaS" }, { k: "f", label: "Serverless" }],
      items: [{ t: "Microsoft Teams", a: "s", why: "" }, { t: "Azure-VM mit eigenem SQL Server", a: "i", why: "Du verwaltest OS und DB-Software selbst." }, { t: "Azure App Service hostet den Webshop", a: "p", why: "" }, { t: "Azure Functions skaliert hochgeladene Produktbilder", a: "f", why: "" }, { t: "Azure SQL Database", a: "p", why: "Managed Database: Anbieter betreibt OS und DB-Engine." }, { t: "Salesforce CRM", a: "s", why: "" }, { t: "Pizza „Take + Bake“", a: "i", why: "" }, { t: "Pizza vom Lieferdienst", a: "p", why: "" }] },
    { t: "callout", html: "Frage 7 der Folie: <b>Wer installiert die Sicherheitspatches für das Betriebssystem einer Azure-VM?</b> → <b>Der Kunde</b>. Bei IaaS liegt das Betriebssystem in der Kundenverantwortung." },
    { t: "check", q: "Pizza „Home Delivery“ entspricht welchem Service-Modell?", opts: ["On-premises", "IaaS", "PaaS", "SaaS"], a: 2, why: "Nur noch Getränke und Tisch (≈ eigene App und Daten) stellst du selbst." }
  ]},
  { id: "itg3-3", title: "Shared Responsibility Model", topic: "itg-shared", min: 12, xp: 0, blocks: [
    { t: "lead", html: "Wer ist wofür verantwortlich? Je höher das Service-Modell, desto mehr übernimmt der Anbieter – aber einiges bleibt immer beim Kunden." },
    { t: "html", html: "<table class='dt'><tr><th>Schicht</th><th>On-prem / Private</th><th>IaaS</th><th>PaaS</th><th>SaaS</th></tr><tr><td>Daten und Zugriff</td><td>Kunde</td><td>Kunde</td><td>Kunde</td><td>Kunde</td></tr><tr><td>Anwendungen</td><td>Kunde</td><td>Kunde</td><td>Kunde</td><td>Anbieter</td></tr><tr><td>Runtime</td><td>Kunde</td><td>Kunde</td><td>Anbieter</td><td>Anbieter</td></tr><tr><td>Betriebssystem</td><td>Kunde</td><td>Kunde</td><td>Anbieter</td><td>Anbieter</td></tr><tr><td>Virtueller Computer</td><td>Kunde</td><td>Anbieter</td><td>Anbieter</td><td>Anbieter</td></tr><tr><td>Compute · Netzwerk · Speicher</td><td>Kunde</td><td>Anbieter</td><td>Anbieter</td><td>Anbieter</td></tr></table>" },
    { t: "text", h: "Was immer beim Kunden bleibt", levels: {
      simple: "Egal ob IaaS, PaaS oder SaaS: Deine Daten, deine Geräte und deine Benutzerkonten sind immer deine Verantwortung.",
      normal: "Unabhängig vom Modell ist der <b>Kunde immer</b> verantwortlich für:<ul><li><b>Informationen und Daten</b> – Klassifizierung, Schutz, Aufbewahrung</li><li><b>Geräte</b> – PCs, Laptops, Handys, die auf den Dienst zugreifen</li><li><b>Konten und Identitäten</b> – wer hat Zugriff? MFA, Least Privilege</li></ul><b>Immer der Anbieter</b>: physisches Rechenzentrum, physisches Netzwerk, physische Hosts.<br><b>Abhängig vom Modell</b>: Betriebssystem, Netzwerkkontrollen, Anwendungen, Identitäts- und Verzeichnisinfrastruktur.<br><br>Die meisten Cloud-Sicherheitsvorfälle entstehen durch <b>Fehlkonfiguration auf Kundenseite</b> – Gartner prognostizierte, dass bis 2025 <b>99 %</b> der Cloud-Security-Failures Kundenfehler sein werden.",
      technical: "Ökonomische Sicht der Folie: Mit Cloud Computing werden Teile der IT-basierten Wertschöpfung an externe Anbieter ausgelagert. Von IaaS über PaaS zu SaaS wird dieser Anteil größer (ebenso die Margen der Anbieter): <b>steigender Lock-in, sinkende operative Komplexität</b>. In umgekehrter Richtung: sinkender Lock-in, steigende Komplexität. Alle Service-Modelle folgen denselben ökonomischen Gesetzen." } },
    { t: "widget", w: "sorter", topic: "itg-shared", title: "Wer ist zuständig?", cats: [{ k: "k", label: "Immer Kunde" }, { k: "a", label: "Immer Anbieter" }, { k: "d", label: "Abhängig vom Modell" }],
      items: [{ t: "Klassifizierung und Aufbewahrung der Daten", a: "k", why: "" }, { t: "Physisches Rechenzentrum", a: "a", why: "" }, { t: "Betriebssystem", a: "d", why: "IaaS: Kunde · PaaS/SaaS: Anbieter." }, { t: "MFA für Benutzerkonten", a: "k", why: "Konten und Identitäten." }, { t: "Physische Hosts", a: "a", why: "" }, { t: "Laptops der Mitarbeitenden", a: "k", why: "Geräte." }, { t: "Netzwerkkontrollen", a: "d", why: "" }, { t: "Physisches Netzwerk", a: "a", why: "" }, { t: "Anwendungen", a: "d", why: "" }] },
    { t: "warnbox", html: "Klassischer Irrtum: „Bei SaaS ist der Anbieter für alles verantwortlich.“ Falsch – <b>Daten, Geräte und Identitäten</b> bleiben auch bei SaaS beim Kunden." },
    { t: "check", q: "Was ist laut Folie die häufigste Ursache von Cloud-Sicherheitsvorfällen?", opts: ["Hardwaredefekte beim Anbieter", "Fehlkonfiguration auf Kundenseite", "Naturkatastrophen", "Zu viele Rechenzentren"], a: 1, why: "Gartner: bis 2025 99 % der Cloud-Security-Failures durch den Kunden." }
  ]},
  { id: "itg3-4", title: "Cloud Benefits & SLAs berechnen", topic: "itg-sla", min: 16, xp: 0, blocks: [
    { t: "lead", html: "Die Vorteile der Cloud, strukturiert wie in der AZ-900-Prüfung – und wie man Verfügbarkeit tatsächlich ausrechnet." },
    { t: "text", h: "Cloud Benefits", levels: {
      simple: "Die Cloud ist hochverfügbar, wächst mit, ist weltweit verfügbar und schnell eingerichtet.",
      normal: "Liste der Folie: High availability · Fault tolerance · Scalability · Elasticity · Global reach · Customer latency capabilities · Agility · Predictive cost considerations · Disaster recovery · Security.<ul><li><b>High availability</b>: je nach gewähltem <b>SLA</b> kontinuierliche Nutzererfahrung ohne sichtbare Ausfälle, auch wenn etwas schiefgeht.</li><li><b>Scalability</b>: <b>vertikal</b> (scale up) = mehr RAM/CPUs für eine VM; <b>horizontal</b> (scale out) = mehr Instanzen, z. B. zusätzliche VMs.</li><li><b>Elasticity</b>: <b>Autoscaling</b> sorgt dafür, dass die App immer die nötigen Ressourcen hat.</li><li><b>Agility</b>: Ressourcen schnell bereitstellen und konfigurieren, wenn sich Anforderungen ändern.</li><li><b>Global reach</b>: Apps und Daten in regionalen Rechenzentren weltweit → beste Performance in jeder Region.</li><li><b>Disaster recovery</b>: Backup-Services, Datenreplikation und Geo-Verteilung schützen Daten im Katastrophenfall.</li></ul>",
      technical: "Die Zusammenfassung der Folie gruppiert die Benefits wie AZ-900: <b>Availability & Scalability</b>, <b>Reliability & Predictability</b>, <b>Security & Governance</b>, <b>Manageability</b>. Skalierbarkeit = Fähigkeit zu wachsen; Elastizität = automatisches, bedarfsgerechtes Wachsen <i>und</i> Schrumpfen." } },
    { t: "html", html: "<table class='dt'><tr><th>Verfügbarkeit</th><th>max. Ausfall pro Jahr</th></tr><tr><td>99 %</td><td>3,65 Tage</td></tr><tr><td>99,9 %</td><td>8,76 Stunden</td></tr><tr><td>99,95 %</td><td>4,38 Stunden</td></tr><tr><td>99,99 %</td><td>52,6 Minuten</td></tr><tr><td>99,999 %</td><td>5,26 Minuten</td></tr></table><p>Azure-VMs (laut Folie, Werte können sich ändern): <b>einzelne VM</b> (Premium SSD) 99,9 % · <b>Availability Set</b> 99,95 % · über <b>Availability Zones</b> 99,99 %.</p>" },
    { t: "text", h: "Composite SLA: seriell und parallel", levels: {
      simple: "Braucht man mehrere Dienste gleichzeitig, multipliziert man die Verfügbarkeiten – das Ergebnis wird schlechter. Hat man Redundanz, wird es besser.",
      normal: "<b>Ausfallzeit</b> = (1 − Verfügbarkeit) × 8.760 h/Jahr.<br><b>Seriell</b> (alle Dienste werden benötigt): Verfügbarkeiten <b>multiplizieren</b>. App Service 99,95 % × SQL Database 99,99 % = <b>99,94 %</b> → ≈ <b>5,3 h/Jahr</b> Ausfall.<br><b>Parallel</b> (redundant, n unabhängige Instanzen): <b>1 − (1 − A)ⁿ</b>. Zwei unabhängige Regionen mit je 99,95 %: 1 − 0,0005² ≈ <b>99,99998 %</b>.<br><br><b>Übung der Folie</b>: Webshop mit App Service (99,95 %), SQL Database (99,99 %) und Storage (99,9 %): 0,9995 × 0,9999 × 0,999 ≈ <b>99,84 %</b> → ≈ 14 h Ausfall pro Jahr.",
      technical: "<pre><code>seriell:  A = A1 × A2 × … × An\nparallel: A = 1 − (1 − A1)(1 − A2)…(1 − An)\nAusfall:  (1 − A) × 365 × 24 h\n\n0,9995 × 0,9999         = 0,99940  → 0,0006 × 8760 h ≈ 5,3 h\n0,9995 × 0,9999 × 0,999 = 0,99840  → 0,0016 × 8760 h ≈ 14 h\n1 − 0,0005²             = 0,99999975</code></pre>Die serielle Verfügbarkeit ist immer <b>kleiner</b> als die des schwächsten Glieds. Die Parallelformel setzt <b>unabhängige</b> Ausfälle voraus – zwei VMs im selben Rack sind das nicht (darum Availability Sets/Zones/Regionen)." } },
    { t: "widget", w: "gapfill", topic: "itg-sla", title: "SLA-Rechnen", items: [{ s: "99,9 % Verfügbarkeit erlauben pro Jahr ca. ___ Stunden Ausfall.", a: ["8,76", "8.76", "8,8", "8.8"] }, { s: "Zwei Dienste mit 99,9 % und 99,95 % seriell ergeben gerundet ___ %.", a: ["99,85", "99.85"] }, { s: "Für redundante Komponenten gilt die Formel 1 − (1 − A)^___ .", a: ["n"] }, { s: "Mehr RAM und CPUs für eine VM nennt man ___ Skalierung.", a: ["vertikale", "vertikal", "vertical"] }, { s: "Zusätzliche VM-Instanzen hinzufügen nennt man ___ Skalierung.", a: ["horizontale", "horizontal"] }] },
    { t: "check", q: "Review-Frage 5: Composite SLA zweier serieller Dienste mit 99,9 % und 99,95 %?", opts: ["99,95 %", "99,925 %", "≈ 99,85 %", "≈ 99,9999 %"], a: 2, why: "0,999 × 0,9995 = 0,9985005 ≈ 99,85 % – schlechter als jeder Einzeldienst." },
    { t: "check", q: "Was erhöht die Verfügbarkeit einer Anwendung?", opts: ["Weitere Dienste seriell davorschalten", "Redundante Instanzen in unabhängigen Zonen/Regionen", "Eine größere einzelne VM", "Weniger Monitoring"], a: 1, why: "Parallel: 1 − (1 − A)ⁿ steigt mit n. Vertikale Skalierung verbessert nicht die Verfügbarkeit." }
  ]}
 ]},
 { id: "itgw4", n: 4, title: "Cloud Economics", sub: "Skaleneffekte, Workloads, p/a, Pricing", boss: { id: "boss-itgw4", title: "Kapiteltest: Cloud Economics", topics: ["itg-scale", "itg-workload", "itg-pa", "itg-cost"] }, lessons: [
  { id: "itg4-1", title: "Economies of Scale", topic: "itg-scale", min: 12, xp: 0, blocks: [
    { t: "lead", html: "Ökonomie formt Branchen stärker als Technik: Technische Hürden werden durch Innovation gelöst – die zugrunde liegende Ökonomie bestimmt Richtung und Tempo." },
    { t: "text", h: "Weder Mainframe noch Client/Server – beides", levels: {
      simple: "Die Cloud ist groß und effizient wie ein Großrechner, aber flexibel wie viele kleine Server.",
      normal: "Cloud Computing vereint die besten ökonomischen Eigenschaften von <b>Mainframe</b> und <b>Client/Server</b>. Es ist <b>keine Rückkehr zur Mainframe-Ära</b>: Die Cloud bietet Skaleneffekte und Effizienz, die die eines Mainframes <b>übertreffen</b>, kombiniert mit <b>Modularität und Agilität</b> jenseits dessen, was Client/Server bot – der frühere Trade-off zwischen Effizienz und Flexibilität entfällt. Wegbereiter dafür war die <b>Virtualisierung</b>.",
      technical: "Diese Begründung ist die erwartete Antwort auf Review-Frage 6 („Warum ist die Cloud keine Rückkehr zur Mainframe-Ära?“). Quelle: Microsoft, The Economics of the Cloud (2010)." } },
    { t: "html", html: "<table class='dt'><tr><th>Skaleneffekt</th><th>Kernaussage</th></tr><tr><td><b>Buying power</b></td><td>Große Betreiber erhalten bis zu <b>30 %</b> Rabatt auf Hardware gegenüber kleinen Käufern – ermöglicht durch Standardisierung auf wenige Hardware-/Software-Architekturen (<b>Infrastrukturhomogenität</b>)</td></tr><tr><td><b>Infrastructure labor costs</b></td><td>Automatisierung wiederkehrender Verwaltungsaufgaben senkt Personalkosten in jeder Größe; große Anlagen noch stärker</td></tr><tr><td><b>Security & reliability</b></td><td>Weitgehend <b>fixe Investition</b> für Sicherheit und Zuverlässigkeit → Skaleneffekt; große Anbieter haben mehr Expertise als typische Unternehmens-IT</td></tr><tr><td><b>Cost of power</b></td><td>Strom wird zum größten TCO-Posten; große Anlagen haben bessere <b>PUE</b>, kaufen Strom billiger in großen Mengen und bauen an Standorten mit günstigem Strom</td></tr></table>" },
    { t: "tip", html: "Gene Spafford: „The only truly secure system is one that is powered off, cast in a block of concrete and sealed in a lead-lined room with armed guards — and even then I have my doubts.“ – Sicherheit ist nie absolut; große Anbieter können sie aber effizienter herstellen." },
    { t: "widget", w: "pairs", topic: "itg-scale", title: "Skaleneffekt ↔ Mechanismus", pairs: [["Buying power", "bis zu 30 % Hardwarerabatt durch Homogenität"], ["Infrastructure labor costs", "Automatisierung repetitiver Verwaltungsaufgaben"], ["Security & reliability", "fixe Investition verteilt auf viele Kunden"], ["Cost of power", "niedrigere PUE und günstige Strom-Standorte"]] },
    { t: "check", q: "Warum führt Sicherheit laut Folie zu Skaleneffekten?", opts: ["Weil Security in der Cloud gratis ist", "Weil das Investment für Sicherheit und Zuverlässigkeit weitgehend fix ist und sich auf viele Kunden verteilt", "Weil Kunden keine Sicherheit brauchen", "Weil Rechenzentren keinen Strom brauchen"], a: 1, why: "Fixkosten pro Kunde sinken mit der Größe; zudem bündeln große Anbieter tiefe Expertise." }
  ]},
  { id: "itg4-2", title: "Application Workload Patterns", topic: "itg-workload", min: 14, xp: 0, blocks: [
    { t: "lead", html: "Lastschwankungen zwingen zu Kapazitätspuffern, die meist ungenutzt bleiben. Wer viele unterschiedliche Workloads bündelt (Pooling), glättet die Schwankungen." },
    { t: "html", html: "<table class='dt'><tr><th>Muster</th><th>Beispiel</th><th>Gegenmittel durch Pooling</th></tr><tr><td><b>Randomness</b></td><td>Leute checken E-Mails zu zufälligen Zeiten; für SLAs braucht es Puffer</td><td>gepoolte Server reduzieren die Variabilität</td></tr><tr><td><b>Time-of-day</b></td><td>Consumer-Dienste peaken abends, Arbeitsplatz-Dienste tagsüber</td><td>mehrere Zeitzonen oder komplementäre Muster (Consumer + Enterprise) auf denselben Servern</td></tr><tr><td><b>Industry-specific</b></td><td>Handel vor Weihnachten, US-Steuerfirmen vor dem 15. April; vorhersehbar (Steuer, Olympia) oder unvorhersehbar (Breaking News)</td><td>starke Diversifikationsvorteile über Branchen</td></tr><tr><td><b>Multi-resource</b></td><td>Suche braucht viel CPU, E-Mail viel Storage – Server kommen aber als Bündel (CPU, Storage, I/O)</td><td>Workloads mit komplementären Ressourcenprofilen kombinieren</td></tr><tr><td><b>Uncertain growth</b></td><td>„TechCrunch-Effekt“ bei Startups; Investitionen müssen vor Kenntnis der Nachfrage genehmigt werden, lange Vorlaufzeit</td><td>Kapazität kurzfristig beziehen statt vorab kaufen</td></tr></table>" },
    { t: "text", h: "Sizing-Problem und Workload-Kategorien", levels: {
      simple: "Im eigenen Rechenzentrum kauft man für die Spitze und hat oft zu viel oder zu wenig. Die Cloud folgt der Lastkurve.",
      normal: "Im klassischen Rechenzentrum entsteht ein <b>Sizing-Problem</b> (Berkeley-Report): Man hat entweder <b>Überkapazität</b> (bezahlt, aber ungenutzt) oder <b>Unterkapazität</b> (verlorene Kunden). Cloud Computing ermöglicht es, der <b>Lastkurve genauer zu folgen</b> und Ressourcen zu sparen.<br><br>Workload-Kategorien nach <i>Cloud Computing Patterns</i> (Fehling et al.):<ul><li><b>Static</b> – konstante Last; statische Skalierung reicht.</li><li><b>Continuously changing</b> – Last wächst (oder sinkt) stetig; statisch muss man in Stufen vorab zukaufen.</li><li><b>Periodic</b> – wiederkehrende Spitzen (täglich, wöchentlich, saisonal).</li><li><b>Unpredictable / once-in-a-lifetime</b> – seltene, unvorhersehbare Spitze.</li></ul>In den Diagrammen ist bei <b>statischer Skalierung</b> die IT-Kapazität eine Linie auf Höhe der Spitze; bei <b>elastischer Skalierung</b> folgt sie der tatsächlichen Last.",
      technical: "Je größer der Abstand zwischen Spitzen- und Durchschnittslast, desto mehr bringt Elastizität – das ist genau das p/a-Verhältnis der nächsten Lektion. Unvorhersehbare Spitzen sind on-premises am teuersten, weil Kapazität für ein seltenes Ereignis dauerhaft vorgehalten werden muss." } },
    { t: "widget", w: "sorter", topic: "itg-workload", title: "Welches Lastmuster?", cats: [{ k: "r", label: "Randomness" }, { k: "t", label: "Time-of-day" }, { k: "i", label: "Industry-specific" }, { k: "m", label: "Multi-resource" }, { k: "u", label: "Uncertain growth" }],
      items: [{ t: "Startup wird in einem Tech-Blog erwähnt und die Nutzerzahl explodiert", a: "u", why: "TechCrunch-Effekt." }, { t: "Onlineshop hat Spitze im Weihnachtsgeschäft", a: "i", why: "" }, { t: "Streaming-Dienst ist abends am stärksten ausgelastet", a: "t", why: "" }, { t: "Suchdienst braucht viel CPU, aber kaum Speicher", a: "m", why: "" }, { t: "Viele Nutzer rufen zufällig gleichzeitig ihre Mails ab", a: "r", why: "" }, { t: "IT-Budget muss genehmigt werden, bevor die Nachfrage bekannt ist", a: "u", why: "" }, { t: "Steuerberatungssoftware vor dem Abgabetermin", a: "i", why: "" }] },
    { t: "check", q: "Wie lässt sich die Time-of-day-Variabilität ausgleichen?", opts: ["Mehr Server für die Abendspitze kaufen", "Workloads mehrerer Zeitzonen oder mit komplementären Tagesmustern auf denselben Servern betreiben", "Server nachts ausschalten und nie wieder einschalten", "Nur noch SaaS verwenden"], a: 1, why: "Pooling: Consumer-Dienste (abends) + Enterprise-Dienste (tagsüber) ergänzen sich." }
  ]},
  { id: "itg4-3", title: "Ist die Cloud immer billiger? Die p/a-Regel", topic: "itg-pa", min: 18, xp: 0, blocks: [
    { t: "lead", html: "Cloud-Ressourcen dürfen teurer sein als eigene – solange der Aufpreis kleiner ist als das Verhältnis von Spitzen- zu Durchschnittslast." },
    { t: "text", h: "Weinmans Regel", levels: {
      simple: "Wenn du etwas selten brauchst, ist Mieten billiger als Kaufen – selbst wenn die Miete pro Tag viel teurer ist.",
      normal: "Nach J. Weinman (Mathematical Proof of the Inevitability of Cloud Computing, 2011) gilt mit <b>c</b> = Cloud-Kosten (pro Ressourceneinheit), <b>d</b> = In-house-Kosten, <b>p</b> = Spitzenlast (peak), <b>a</b> = Durchschnittslast (average):<pre><code>c / d &lt; p / a   ⇔   c &lt; d · p / a</code></pre>Ein statisches Rechenzentrum muss Kapazität für <b>p</b> vorhalten, nutzt aber im Schnitt nur <b>a</b> (graue Fläche = ungenutzte Ressourcen). In der Cloud folgt die Kapazität dem Bedarf. Deshalb sind Cloud-Ressourcen besonders wirtschaftlich, wenn <b>Lastschwankungen</b> auftreten.<br><br><b>Review-Frage 4</b>: Peak 10 Server, Durchschnitt 2 → p/a = <b>5</b>. Die Cloud bleibt billiger, solange sie pro Ressource <b>weniger als das 5-Fache</b> der In-house-Kosten kostet.",
      technical: "Bei einem perfekt statischen Workload ist p/a = 1 → die Cloud lohnt sich nur, wenn sie pro Einheit billiger ist als in-house. Die Regel vernachlässigt Fixkosten des Wechsels, Egress, Rabattmodelle und Granularität der Abrechnung. Feinere Granularität (kleinere Ressourcen, kürzere Zuteilungsdauer) nähert die Kapazität der Lastkurve weiter an." } },
    { t: "html", html: "<table class='dt'><tr><th colspan='2'>Exkurs: Beispiel Wohnmobil</th></tr><tr><td>Kauf</td><td>92.000 €, Wertverlust 10 % = 9.200 € + Vollkasko 2.500 € = <b>11.700 €</b> im ersten Jahr ≈ <b>32 €/Tag</b></td></tr><tr><td>p</td><td>365/365 = <b>1</b> (jeden Tag nutzbar)</td></tr><tr><td>a</td><td>25/365 ≈ <b>0,0685</b> (25 Tage Camping)</td></tr><tr><td>p/a</td><td>1 / 0,0685 ≈ <b>14,6</b></td></tr><tr><td>Max. akzeptable Tagesmiete</td><td>32 € × 14,6 ≈ <b>467 €</b></td></tr><tr><td>Marktpreis (Hochsaison 2025)</td><td>155 €/Tag inkl. Vollkasko → 25 × 155 € = <b>3.875 €</b> statt 11.700 €</td></tr><tr><td>Sicht des Vermieters</td><td>11.700 € / 155 € ≈ <b>75,5 Miettage</b> zur Kostendeckung</td></tr></table>" },
    { t: "text", h: "Seriell vs. parallel und die Pizza-Workloads", levels: {
      simple: "20 Pizzen in einem Ofen dauern 5 Stunden, in 20 Öfen 15 Minuten – kostet in der Cloud gleich viel. Je unregelmäßiger du Pizza brauchst, desto mehr darf der Pizzadienst kosten.",
      normal: "<b>Seriell vs. parallel</b>: 20 Pizzen à 15 min in einem Ofen = 5 h, in 20 Öfen = 15 min – <b>gleiche Kosten</b>. Bei IaaS ist es finanziell egal, ob man <b>1 VM 1.000 Stunden</b> oder <b>1.000 VMs 1 Stunde</b> betreibt – aber das Ergebnis liegt nach 1 statt 1.000 Stunden vor. On-premises müsste man Hardware für 1.000 VMs kaufen, die danach ungenutzt bliebe.<br><br><b>Pizza-Workloads</b> (Faktor, um den der Pizzadienst teurer sein darf als selbstgemacht):<ul><li><b>Static</b> – jeden Werktag Mittagspizza: bis <b>≈ 1,4×</b> (36 % teurer)</li><li><b>Continuously changing</b> – „Trendsetter“, Kollegen wollen Woche für Woche mehr: bis <b>≈ 3×</b> (3,1)</li><li><b>Periodic</b> – Spieleabende am Wochenende: bis <b>≈ 7×</b> (7,1)</li><li><b>Unpredictable</b> – ab und zu Familie in die Pizzeria: bis <b>≈ 17×</b> (17,1)</li></ul>Fazit: <b>Kostenvorteile entstehen primär aus dem Workload</b> – Static tendiert zu On-Premise, Unpredictable klar zur Cloud.",
      technical: "Rechnung Static: Pizza an 22 von 30 Tagen (Werktage) → p = 1, a = 22/30 ≈ 0,73 → p/a ≈ 1,36. <b>Effekt der feinen Granularität</b> (Kratzke): Derselbe Lastverlauf benötigt bei 4 vCPU/120 min Zuteilung <b>120 vCPU-Stunden</b>, bei 2 vCPU/30 min 68, bei 1 vCPU/30 min 64 und bei 1 vCPU/5 min nur <b>56,42 vCPU-Stunden</b> – der Anteil voll genutzter Ressourcen steigt (bis 66 %)." } },
    { t: "widget", w: "gapfill", topic: "itg-pa", title: "p/a rechnen", items: [{ s: "Peak 10 Server, Durchschnitt 2 Server: p/a = ___.", a: ["5"] }, { s: "Beim Wohnmobil beträgt p/a rund ___.", a: ["14,6", "14.6", "15"] }, { s: "Weinman: Die Cloud lohnt sich, solange c < d · p / ___.", a: ["a"] }, { s: "Bei einem unvorhersehbaren Pizza-Workload darf der Anbieter bis zu ___-mal teurer sein.", a: ["17", "17,1", "17.1"] }] },
    { t: "check", q: "Ein Workload hat eine Spitzenlast von 12 und eine Durchschnittslast von 3 Servern. Die Cloud kostet pro Server das 3-Fache der eigenen Kosten. Was gilt?", opts: ["Die Cloud ist teurer, weil 3 > 1", "Die Cloud ist günstiger, weil 3 < p/a = 4", "Beides kostet gleich viel", "Man kann es ohne absolute Preise nicht sagen"], a: 1, why: "c/d = 3 < p/a = 12/3 = 4 → Cloud wirtschaftlicher." },
    { t: "check", q: "1 VM für 1.000 Stunden oder 1.000 VMs für 1 Stunde – was gilt in der Cloud?", opts: ["Die parallele Variante kostet 1.000-mal mehr", "Kosten gleich, aber das Ergebnis liegt viel früher vor", "Die serielle Variante ist immer billiger", "Parallelbetrieb ist in der Cloud nicht möglich"], a: 1, why: "Gleiche Ressourcenstunden → gleiche Kosten; on-prem müsste man 1.000 VMs an Hardware kaufen." }
  ]},
  { id: "itg4-4", title: "CapEx vs. OpEx, Pricing-Modelle & Kostenfallen", topic: "itg-cost", min: 16, xp: 0, blocks: [
    { t: "lead", html: "Die Cloud verschiebt IT von fixen zu variablen Kosten – aber das passende Preismodell muss zum Workload passen, sonst wird es teuer." },
    { t: "text", h: "CapEx vs. OpEx", levels: {
      simple: "CapEx: Hardware vorab kaufen. OpEx: laufend für das zahlen, was man nutzt.",
      normal: "<b>Capital Expenditure (CapEx)</b>: Vorab-Ausgaben für physische Infrastruktur; der Wert nimmt über die Zeit ab. Betriebswirtschaftlich: <b>Vermögenswert in der Bilanz</b>, abgeschrieben über die Nutzungsdauer (IT-Hardware typisch <b>3–5 Jahre</b>), bindet Kapital vorab, Kapazität für Jahre fixiert.<br><b>Operational Expenditure (OpEx)</b>: Ausgaben für Produkte und Services nach Bedarf, <b>pay-as-you-go</b>, sofort verrechnet. Betriebswirtschaftlich: <b>Aufwand in der GuV</b> der laufenden Periode, kein gebundenes Kapital, Kosten folgen der Nutzung – können aber auch <b>unerwartet steigen</b>.<br><br>Die Cloud verschiebt IT von <b>fixen zu variablen Kosten</b> → niedrigere Einstiegshürde, billige Experimente („<b>fail fast</b>“). <b>Aber</b>: Commitments (Reservierungen, Savings Plans) bringen Fixkostenelemente zurück. Entscheidung auf Basis der <b>Total Cost of Ownership (TCO)</b>: Hardware, Lizenzen, Energie, Fläche, Kühlung, Personal, Ausfallzeiten, Migrations- und Exit-Kosten.",
      technical: "<b>Consumption-based model</b>: Cloud-Anbieter verrechnen nur genutzte Ressourcen – bessere Kostenvorhersage, Preise je Ressource/Service veröffentlicht, Abrechnung nach tatsächlicher Nutzung. Das setzt das NIST-Merkmal <i>Measured service</i> voraus." } },
    { t: "html", html: "<table class='dt'><tr><th>Azure-Preismodell</th><th>Eigenschaft (max. Rabatte laut Folie, können sich ändern)</th><th>passt zu</th></tr><tr><td><b>Pay-as-you-go</b></td><td>pro Sekunde/Stunde, keine Bindung</td><td>periodisch, unvorhersehbar</td></tr><tr><td><b>Reserved Instances</b> (1 oder 3 Jahre)</td><td>bis zu <b>72 %</b> günstiger als Pay-as-you-go</td><td>statische Grundlast</td></tr><tr><td><b>Savings Plan for Compute</b> (1 oder 3 Jahre, stündliche Ausgabenverpflichtung)</td><td>bis zu <b>65 %</b></td><td>statische Grundlast; kontinuierlich wachsend (+ Autoscaling)</td></tr><tr><td><b>Spot VMs</b></td><td>ungenutzte Kapazität mit bis zu <b>90 %</b> Rabatt – können <b>jederzeit verdrängt</b> werden</td><td>unterbrechbare Batch-Jobs</td></tr><tr><td><b>Azure Hybrid Benefit</b></td><td>vorhandene Windows-Server- und SQL-Server-Lizenzen wiederverwenden</td><td>Migration mit Bestandslizenzen</td></tr></table><p>Zuordnung der Folie: Static → Reserved/Savings Plan · Continuously changing → Autoscaling + Savings Plan · Periodic → Autoscaling, Pay-as-you-go, außerhalb der Geschäftszeiten abschalten · Unpredictable → Pay-as-you-go, Serverless · Interruptible Batch → Spot VMs.</p>" },
    { t: "text", h: "Kostenfallen und FinOps", levels: {
      simple: "Die Cloud ist nicht automatisch billiger. Vergessene VMs, zu große VMs und Datentransfer nach draußen kosten Geld.",
      normal: "<b>Weinman</b>: Die Cloud zahlt sich bei hohem p/a aus – bei statischen Workloads kann eigene Hardware billiger sein. <b>Fall 37signals</b> (Basecamp, HEY): Cloud-Rechnung 2022 3,2 Mio. $; nach Umzug auf eigene Hardware (≈ 700 k$ für Server) berichtet die Firma Einsparungen von etwa 2 Mio. $ im Jahr 2024 (<b>Repatriierung</b>).<br><b>Typische Kostenfallen</b>: vergessene Ressourcen (idle VMs, nicht angehängte Disks), überdimensionierte VMs, <b>Egress-Gebühren</b>, fehlende Tags und Budgets.<br><b>FinOps</b>: Cloud-Kosten sichtbar und steuerbar machen – Budgets, Tags, Alerts, <b>Right-Sizing</b> (Azure Cost Management).<br><b>Lock-in-Kosten</b>: proprietäre PaaS-/Serverless-Dienste verteuern den Wechsel; der <b>EU Data Act</b> (anwendbar seit Sept. 2025) verpflichtet Anbieter, Wechselgebühren bis 2027 abzuschaffen.",
      technical: "Egress = Datenverkehr aus der Cloud hinaus (Ingress ist meist kostenlos) – ein zentraler Treiber von Data Gravity und Lock-in. Tags (Schlüssel-Wert-Paare an Ressourcen) ermöglichen Kostenzuordnung nach Projekt/Kostenstelle." } },
    { t: "widget", w: "sorter", topic: "itg-cost", title: "Welches Preismodell passt?", cats: [{ k: "res", label: "Reserved / Savings Plan" }, { k: "payg", label: "Pay-as-you-go / Serverless" }, { k: "spot", label: "Spot VMs" }, { k: "ahb", label: "Azure Hybrid Benefit" }],
      items: [{ t: "ERP-Server, rund um die Uhr gleichmäßig ausgelastet, 3 Jahre geplant", a: "res", why: "Statische Grundlast." }, { t: "Nächtliches Rendering, das jederzeit abbrechen und neu starten darf", a: "spot", why: "" }, { t: "Kampagnen-Website mit unvorhersehbaren Spitzen", a: "payg", why: "" }, { t: "Bestehende SQL-Server-Lizenzen sollen weitergenutzt werden", a: "ahb", why: "" }, { t: "Testumgebung, nur während der Geschäftszeiten benötigt", a: "payg", why: "Periodisch: außerhalb der Geschäftszeiten abschalten." }, { t: "Interruptible Batch-Analyse großer Datenmengen", a: "spot", why: "" }] },
    { t: "check", q: "Welche Aussage über OpEx ist richtig?", opts: ["OpEx wird als Vermögenswert über 3–5 Jahre abgeschrieben", "OpEx ist Aufwand der laufenden Periode, bindet kein Kapital, kann aber unerwartet steigen", "OpEx erfordert immer eine 3-Jahres-Bindung", "OpEx ist immer billiger als CapEx"], a: 1, why: "Abschreibung über Nutzungsdauer betrifft CapEx." },
    { t: "check", q: "Was ist das Risiko von Spot VMs?", opts: ["Sie sind teurer als Pay-as-you-go", "Sie können jederzeit verdrängt (evicted) werden", "Sie benötigen eine 3-Jahres-Bindung", "Sie unterstützen kein Linux"], a: 1, why: "Spot nutzt ungenutzte Kapazität mit bis zu 90 % Rabatt – darum nur für unterbrechbare Jobs." }
  ]}
 ]},
 { id: "itgw5", n: 5, title: "Markt, Risiken & digitale Souveränität", sub: "Prinzipien, Recht, Energie", boss: { id: "boss-itgw5", title: "Kapiteltest: Markt, Risiken, Regulierung", topics: ["itg-dist", "itg-reg"] }, lessons: [
  { id: "itg5-1", title: "Cloud-Markt, Hype Cycle & die 5 Gebote", topic: "itg-dist", min: 14, xp: 0, blocks: [
    { t: "html", html: "<table class='dt'><tr><th>Public-Cloud-Ausgaben (Gartner)</th><th>Marktanteile Cloud-Infrastruktur Q1 2026 (Synergy)</th></tr><tr><td>2024: 595,7 Mrd. $<br>2025: 723,4 Mrd. $ (+21,5 %)<br>2026: weiteres Wachstum ≈ 21 % (Prognose)<br>Haupttreiber: <b>KI</b> (Training und Inferenz); weitere: Hybrid/Multi-Cloud, Sovereign Cloud</td><td>AWS 28 % · Microsoft Azure 21 % · Google Cloud 14 %<br>Big Three zusammen <b>63 %</b>, Rest stark fragmentiert<br>Q1 2026 Ausgaben: 129 Mrd. $ (+35 % ggü. Vorjahr)</td></tr></table>" },
    { t: "text", h: "Hype Cycle und die 5 Gebote der Cloud", levels: {
      simple: "Neue Technologien werden erst überschätzt, dann unterschätzt, dann produktiv genutzt. In der Cloud plant man mit Ausfällen.",
      normal: "<b>Gartner Hype Cycle</b>: Innovation Trigger → Peak of Inflated Expectations → Trough of Disillusionment → Slope of Enlightenment → Plateau of Productivity (Erwartungen über Zeit).<br><br><b>Die 5 Gebote der Cloud</b>:<ol><li><b>Everything fails all the time</b> – Ausfälle sind normal, nicht die Ausnahme.</li><li>Fokus auf <b>MTTR</b> (Mean Time to Repair) statt <b>MTTF</b> (Mean Time to Failure) – schnell wiederherstellen ist wichtiger als Ausfälle zu verhindern.</li><li>Die <b>8 Fallacies of Distributed Computing</b> respektieren.</li><li><b>Scale out, not up</b> – horizontal statt vertikal skalieren.</li><li><b>Treat resources as cattle, not pets</b> – Ressourcen sind austauschbar (automatisiert neu erzeugen statt liebevoll pflegen).</li></ol>",
      technical: "Cattle vs. Pets: Ein „Pet“-Server hat einen Namen und wird bei Problemen repariert; „Cattle“ werden aus Images/Templates erzeugt und bei Problemen ersetzt (Infrastructure as Code, Immutable Infrastructure). Scale out passt zur Parallelformel der SLAs: mehrere Instanzen erhöhen Kapazität und Verfügbarkeit, eine größere VM bleibt ein Single Point of Failure." } },
    { t: "text", h: "Die 8 Fallacies of Distributed Computing", levels: {
      simple: "Acht falsche Annahmen über Netzwerke, die Entwickler oft treffen – z. B. „das Netz fällt nie aus“.",
      normal: "<ol><li>The network is reliable</li><li>Latency is zero</li><li>Bandwidth is infinite</li><li>The network is secure</li><li>Topology doesn't change</li><li>There is one administrator</li><li>Transport cost is zero</li><li>The network is homogeneous</li></ol>Trivial klingende, aber oft unbewusst getroffene Annahmen beim (ersten) Entwickeln verteilter Anwendungen.",
      technical: "Herkunft: Sun Microsystems – Bill Joy und Tom Lyon begannen mit vier Fallacies; Peter Deutsch erweiterte 1994 auf sieben („The Seven Fallacies of Distributed Computing“); James Gosling ergänzte um 1997 die achte (The network is homogeneous). „Transport cost is zero“ hat in der Cloud eine ganz konkrete Form: Egress-Gebühren." } },
    { t: "widget", w: "sorter", topic: "itg-dist", title: "Fallacy oder Wahrheit?", cats: [{ k: "f", label: "Fallacy (falsche Annahme)" }, { k: "w", label: "Cloud-Prinzip (richtig)" }],
      items: [{ t: "The network is reliable", a: "f", why: "" }, { t: "Everything fails all the time", a: "w", why: "" }, { t: "Latency is zero", a: "f", why: "" }, { t: "Scale out, not up", a: "w", why: "" }, { t: "There is one administrator", a: "f", why: "" }, { t: "Treat resources as cattle, not pets", a: "w", why: "" }, { t: "Transport cost is zero", a: "f", why: "" }, { t: "Focus on MTTR rather than MTTF", a: "w", why: "" }, { t: "Topology doesn't change", a: "f", why: "" }] },
    { t: "check", q: "Was bedeutet „Treat resources as cattle, not pets“?", opts: ["Ressourcen individuell pflegen und reparieren", "Ressourcen als austauschbar behandeln und bei Problemen automatisiert ersetzen", "Nur Tierdaten in der Cloud speichern", "Ressourcen nie löschen"], a: 1, why: "Pets werden gepflegt, Cattle werden ersetzt – Basis für Automatisierung und Resilienz." }
  ]},
  { id: "itg5-2", title: "Risiken, Recht, Souveränität & Energie", topic: "itg-reg", min: 18, xp: 0, blocks: [
    { t: "lead", html: "Wo liegen die Daten – und wer kann darauf zugreifen? Datenresidenz ist nicht dasselbe wie Datensouveränität." },
    { t: "keys", items: ["<b>Vendor Lock-in</b>: proprietäre Dienste, Data Gravity, Egress-Kosten → Exit-Strategie ab Tag 1", "<b>Abhängigkeit & Ausfälle</b>: Ausfall eines großen Anbieters (z. B. AWS us-east-1, Oktober 2025) trifft Tausende Kunden gleichzeitig", "<b>Compliance & Datenschutz</b>, <b>Kostenkontrolle</b> (FinOps), <b>Skills</b> (Architektur, Security, Kostenmanagement)", "<b>Netzwerkabhängigkeit</b>: Latenz, Bandbreite, Verfügbarkeit der Internetanbindung", "<b>Security</b>: Shared Responsibility – Fehlkonfiguration ist die häufigste Ursache"] },
    { t: "html", html: "<table class='dt'><tr><th>Regelung</th><th>Kernaussage laut Folie</th></tr><tr><td><b>DSGVO / GDPR</b></td><td>personenbezogene Daten dürfen die EU nur mit angemessenen Garantien verlassen (z. B. EU-US Data Privacy Framework seit Juli 2023)</td></tr><tr><td><b>US CLOUD Act</b> (2018)</td><td>US-Behörden können Daten von US-Anbietern verlangen – <b>auch wenn sie in der EU gespeichert</b> sind</td></tr><tr><td><b>EU Data Boundary</b> (Microsoft, abgeschlossen Feb. 2025)</td><td>hält Daten in EU/EFTA – der Anbieter bleibt aber US-Recht unterworfen</td></tr><tr><td><b>NIS2</b></td><td>Cybersecurity-Pflichten für wesentliche und wichtige Einrichtungen – inkl. Lieferkette und Cloud-Anbieter</td></tr><tr><td><b>DORA</b> (seit Jan. 2025)</td><td>IKT-Risikomanagement im <b>Finanzsektor</b>, inkl. Aufsicht über kritische IKT-Drittanbieter</td></tr><tr><td><b>EU Data Act</b> (seit Sept. 2025)</td><td>erleichterter Wechsel zwischen Cloud-Anbietern; Wechselgebühren bis 2027 abschaffen</td></tr><tr><td><b>Sovereign-Cloud-Angebote</b></td><td>Microsoft Sovereign Cloud, AWS European Sovereign Cloud, europäische Anbieter wie IONOS, STACKIT, OVHcloud</td></tr></table>" },
    { t: "text", h: "Datenresidenz vs. Datensouveränität", levels: {
      simple: "Daten in Europa speichern heißt nicht automatisch, dass nur Europa darauf zugreifen darf.",
      normal: "<b>Data Residency</b> = <b>wo</b> die Daten physisch gespeichert werden (z. B. EU-Rechenzentrum). <b>Data Sovereignty</b> = <b>welchem Recht</b> die Daten unterliegen und wer sie kontrolliert bzw. Zugriff erzwingen kann. Ein US-Anbieter mit EU-Rechenzentrum erfüllt Residenz, bleibt aber über den <b>CLOUD Act</b> US-Recht unterworfen.<br><br><b>Digitale Souveränität</b> – Beispiel der Folie: Im Juni 2025 sagte Anton Carniaux (General Manager Microsoft Frankreich) unter Eid vor dem französischen Senat, er könne <b>nicht garantieren</b>, dass Daten französischer Bürger nicht ohne Zustimmung der französischen Regierung an ausländische Behörden weitergegeben werden. Auch Vertreter von AWS, Google und Salesforce erklärten, europäische Kundendaten bei Gerichtsbeschluss an US-Behörden herauszugeben. Kritiker sprechen von „Sovereignty Washing“.",
      technical: "Diese Unterscheidung ist Review-Frage 7. Rechtsquellen: DSGVO (VO (EU) 2016/679), DORA (VO (EU) 2022/2554), Data Act (VO (EU) 2023/2854), NIS2 (RL (EU) 2022/2555). Verordnungen gelten unmittelbar, die NIS2-Richtlinie muss national umgesetzt werden." } },
    { t: "text", h: "Nachhaltigkeit und Energie", levels: {
      simple: "Rechenzentren brauchen viel Strom, durch KI immer mehr. Große Anbieter sind effizienter als kleine Serverräume.",
      normal: "Rechenzentren verbrauchten 2024 ca. <b>415 TWh</b> (≈ <b>1,5 %</b> des weltweiten Stroms). Prognose: ca. <b>945 TWh bis 2030</b> – mehr als doppelt so viel, etwas mehr als der heutige Gesamtverbrauch Japans; <b>KI</b> ist der Haupttreiber (IEA, Energy and AI 2025).<br><b>PUE (Power Usage Effectiveness)</b> = Gesamtenergie der Anlage ÷ Energie der IT-Geräte. Große Anbieter erreichen Werte <b>nahe 1,1</b>, viele kleine Serverräume liegen weit darüber. Anbieter sichern sich langfristig Strom – sogar aus Kernkraft (z. B. Reaktivierung von Three Mile Island für Microsoft).<br><b>Deine Hebel</b>: Right-Sizing, automatisches Abschalten, Regionen mit CO₂-armem Strom wählen, Emissionen messen (z. B. Microsoft Emissions Impact Dashboard).",
      technical: "PUE = 1,0 wäre ideal (gesamte Energie geht in die IT). PUE 1,1 bedeutet 10 % Overhead für Kühlung, Stromverteilung usw.; ein kleiner Serverraum mit PUE 2,0 verbraucht für jede kWh IT eine weitere kWh Overhead." } },
    { t: "widget", w: "pairs", topic: "itg-reg", title: "Regelung ↔ Inhalt", pairs: [["CLOUD Act", "US-Behörden können Daten von US-Anbietern auch aus der EU verlangen"], ["DORA", "IKT-Risikomanagement im Finanzsektor"], ["NIS2", "Cybersecurity-Pflichten für wesentliche/wichtige Einrichtungen inkl. Lieferkette"], ["EU Data Act", "erleichterter Anbieterwechsel, Wechselgebühren fallen bis 2027"], ["DSGVO", "Datentransfer aus der EU nur mit angemessenen Garantien"], ["PUE", "Gesamtenergie ÷ Energie der IT-Geräte"]] },
    { t: "warnbox", html: "„Unsere Daten liegen in Frankfurt, also gilt nur EU-Recht“ – <b>falsch</b>, wenn der Anbieter ein US-Unternehmen ist. Residenz ≠ Souveränität." },
    { t: "check", q: "Ein US-Hyperscaler speichert Daten ausschließlich in der EU. Was gilt?", opts: ["Die Daten sind vollständig vor US-Zugriff geschützt", "Datenresidenz ist erfüllt, aber über den CLOUD Act bleibt der Anbieter US-Recht unterworfen", "Die DSGVO gilt dann nicht", "DORA verbietet das"], a: 1, why: "Genau der Unterschied zwischen Data Residency und Data Sovereignty." },
    { t: "check", q: "Ein Rechenzentrum verbraucht insgesamt 1.320 MWh, die IT-Geräte davon 1.200 MWh. PUE?", opts: ["0,91", "1,1", "1,2", "120"], a: 1, why: "PUE = 1.320 / 1.200 = 1,1 – typischer Wert großer Anbieter." }
  ]}
 ]},
 { id: "itgw6", n: 6, title: "Ausblick laut Syllabus: Azure in der Praxis", sub: "Noch nicht auf Folien – Überblick für die Laborübungen", boss: null, lessons: [
  { id: "itg6-1", title: "Azure-Basiskomponenten", topic: "itg-azure", min: 12, xp: 0, blocks: [
    { t: "callout", html: "<b>Ausblick laut Syllabus</b>: Diese Inhalte stehen im Syllabus, sind aber noch nicht durch Folien abgedeckt. Die Erklärungen sind allgemeines Azure-Grundwissen (AZ-900/AZ-104) – Details folgen in Vorlesung und Labor." },
    { t: "text", h: "Was im Labor verwendet wird", levels: {
      simple: "Im Labor baust du in Azure virtuelle Maschinen, Speicher, Netzwerke, Backups und DNS selbst auf.",
      normal: "Laut Syllabus werden zentrale Azure-Infrastrukturkomponenten verwendet und verwaltet:<ul><li><b>Virtuelle Maschinen</b> – IaaS-Compute (Größe, Image, Disks, Verfügbarkeitsoptionen wie Availability Sets/Zones)</li><li><b>Azure Storage</b> – Speicherkonto mit Diensten wie Blob, Files, Queues, Tables</li><li><b>Virtuelle Netzwerke (VNets)</b> – isolierte private Netze mit Subnetzen; Netzwerksicherheitsgruppen (NSGs) filtern Verkehr</li><li><b>Backup und Restore</b> – Sicherung und Wiederherstellung (z. B. Azure Backup mit einem Recovery Services Vault)</li><li><b>Azure DNS</b> – Namensauflösung mit <b>öffentlichen</b> Zonen (aus dem Internet auflösbar) und <b>privaten</b> Zonen (nur innerhalb verknüpfter VNets)</li></ul>",
      technical: "Organisationshierarchie in Azure: <b>Management Groups → Subscriptions → Resource Groups → Resources</b>. Jede Ressource liegt in genau einer Resource Group und wird in einer <b>Region</b> bereitgestellt; manche Regionen bieten <b>Availability Zones</b> (physisch getrennte Rechenzentren innerhalb einer Region). Verwaltet wird über Azure Portal, Azure CLI, PowerShell oder Templates (ARM/Bicep)." } },
    { t: "keys", items: ["Zugang zu Microsoft Azure wird zu Beginn der LV gemeinsam eingerichtet bzw. bereitgestellt", "Vorausgesetzt: Grundkenntnisse in Betriebssystemen und Netzwerktechnik (vgl. Linux/Windows-LVs aus Semester 1–2)", "Primäre Ressource: Microsoft-Dokumentation und Microsoft Learn – Lernpfade AZ-900 und AZ-104", "Themen der LV: Grundlagen des Cloud Computings · Administration der Cloud am Beispiel Azure · Basiskomponenten für einfache IT-Architekturen"] },
    { t: "widget", w: "pairs", topic: "itg-azure", title: "Azure-Dienst ↔ Zweck", pairs: [["Virtual Machine", "IaaS-Rechenleistung mit eigenem Betriebssystem"], ["Virtual Network (VNet)", "isoliertes privates Netzwerk mit Subnetzen"], ["Azure Storage", "Speicherkonto für Blobs, Dateien, Queues, Tables"], ["Private DNS Zone", "Namensauflösung nur innerhalb verknüpfter VNets"], ["Resource Group", "logischer Container für zusammengehörige Ressourcen"], ["Azure Backup", "Sicherung und Wiederherstellung von VMs und Daten"]] },
    { t: "check", q: "Was unterscheidet eine private von einer öffentlichen Azure-DNS-Zone?", opts: ["Private Zonen sind kostenlos, öffentliche nicht", "Private Zonen lösen Namen nur innerhalb verknüpfter VNets auf, öffentliche aus dem Internet", "Öffentliche Zonen gibt es nur in den USA", "Es gibt keinen Unterschied"], a: 1, why: "Laut Syllabus werden beide Varianten mit Azure DNS aufgebaut." }
  ]},
  { id: "itg6-2", title: "Identität, Zugriff & Sicherheit", topic: "itg-azid", min: 14, xp: 0, blocks: [
    { t: "callout", html: "<b>Ausblick laut Syllabus</b>: Verzeichnisdienste, RBAC, Azure Policy, Key Vault, Conditional Access und MFA sind Lernergebnisse der LV, aber noch nicht in den Folien. Hier ein stabiler Grundüberblick." },
    { t: "text", h: "Verzeichnisdienste und hybride Identität", levels: {
      simple: "Ein Verzeichnisdienst ist das zentrale „Telefonbuch“ für Benutzer, Gruppen und Geräte. In der Cloud heißt er bei Microsoft Entra ID.",
      normal: "Zentrale <b>Verzeichnisdienste</b> verwalten Identitäten und Ressourcen – klassisch on-premises mit <b>Active Directory Domain Services</b>, in der Cloud mit <b>Microsoft Entra ID</b> (früher Azure Active Directory). In <b>hybriden Szenarien</b> werden lokale und Cloud-Identitäten verbunden:<ul><li><b>Verzeichnissynchronisierung</b>: Benutzer/Gruppen aus dem lokalen AD werden nach Entra ID synchronisiert (z. B. Microsoft Entra Connect).</li><li><b>Verbund-/Föderationsdienste</b>: Vertrauensstellung zwischen Identitätsanbietern, sodass sich Benutzer über Unternehmensgrenzen hinweg mit ihrer Heimat-Identität anmelden (Single Sign-On, z. B. via SAML/OpenID Connect).</li></ul>",
      technical: "Unterschied: Bei Synchronisierung existiert eine Kopie des Objekts im Zielverzeichnis; bei Föderation bleibt die Authentifizierung beim Heimat-Identitätsanbieter, der Dienst vertraut dessen signiertem Token." } },
    { t: "text", h: "RBAC, Azure Policy, Key Vault, Conditional Access", levels: {
      simple: "RBAC regelt, wer was darf. Policy regelt, wie Ressourcen aussehen müssen. Key Vault schützt Geheimnisse. MFA und Conditional Access sichern die Anmeldung.",
      normal: "<b>Role-Based Access Control (RBAC)</b>: Eine <b>Rollenzuweisung</b> besteht aus <b>Sicherheitsprinzipal</b> (wer: Benutzer, Gruppe, Service Principal, Managed Identity) + <b>Rollendefinition</b> (was: z. B. Owner, Contributor, Reader) + <b>Bereich/Scope</b> (wo: Management Group, Subscription, Resource Group, Ressource). Berechtigungen werden an untergeordnete Scopes vererbt; Prinzip <b>Least Privilege</b>.<br><b>Azure Policy</b>: zentrales Konfigurationsmanagement – Regeln für Ressourceneigenschaften (z. B. „nur Region West Europe“, „Tags verpflichtend“), die geprüft (audit) oder erzwungen (deny) werden. RBAC = <i>wer darf handeln</i>, Policy = <i>welcher Zustand ist erlaubt</i>.<br><b>Azure Key Vault</b>: sichere Verwaltung von <b>Secrets</b> (Passwörter, Connection Strings), <b>Schlüsseln</b> (Verschlüsselung, Signatur) und <b>Zertifikaten</b>.<br><b>MFA</b>: mindestens zwei Faktoren aus Wissen (Passwort), Besitz (Handy/Token) und Inhärenz (Biometrie). <b>Conditional Access</b>: richtlinienbasierte Wenn-dann-Regeln, die Signale (Benutzer, Gerät, Standort, Risiko, Anwendung) auswerten und z. B. MFA verlangen oder Zugriff blockieren.",
      technical: "Verschlüsselung (Vertraulichkeit) vs. digitale Signatur (Integrität und Authentizität): Bei asymmetrischen Verfahren wird mit dem <b>öffentlichen</b> Schlüssel des Empfängers verschlüsselt und mit dem <b>privaten</b> Schlüssel des Empfängers entschlüsselt; signiert wird mit dem <b>privaten</b> Schlüssel des Absenders und mit dessen <b>öffentlichem</b> Schlüssel verifiziert. Zertifikate binden einen öffentlichen Schlüssel an eine Identität (ausgestellt von einer CA)." } },
    { t: "widget", w: "sorter", topic: "itg-azid", title: "Welcher Dienst/Mechanismus?", cats: [{ k: "rbac", label: "RBAC" }, { k: "pol", label: "Azure Policy" }, { k: "kv", label: "Key Vault" }, { k: "ca", label: "Conditional Access / MFA" }, { k: "dir", label: "Entra ID / Verzeichnis" }],
      items: [{ t: "Gruppe „Support“ erhält die Rolle Reader auf eine Resource Group", a: "rbac", why: "" }, { t: "Ressourcen ohne Tag „Kostenstelle“ dürfen nicht erstellt werden", a: "pol", why: "" }, { t: "Connection String der Datenbank sicher ablegen", a: "kv", why: "" }, { t: "Anmeldung von außerhalb Österreichs erfordert zusätzlich einen Code am Handy", a: "ca", why: "" }, { t: "Benutzerkonten aus dem lokalen AD werden in die Cloud synchronisiert", a: "dir", why: "" }, { t: "TLS-Zertifikat für den Webshop verwalten", a: "kv", why: "" }, { t: "Nur VMs in der Region West Europe erlauben", a: "pol", why: "" }] },
    { t: "check", q: "Woraus besteht eine Azure-RBAC-Rollenzuweisung?", opts: ["Benutzername + Passwort + MFA", "Sicherheitsprinzipal + Rollendefinition + Scope", "Subscription + Region + Tag", "Policy + Initiative + Effekt"], a: 1, why: "Wer (Principal), was (Rolle), wo (Scope)." }
  ]},
  { id: "itg6-3", title: "So läuft ITINF-GL", topic: "itg-azure", min: 6, xp: 0, blocks: [
    { t: "keys", items: ["Integrierte Lehrveranstaltung: <b>22,5 LE Vorlesung</b> (Nestler) + <b>30 LE Übungen</b> (je 15 LE Nestler und Gölles); 3,5 SWS, 5 ECTS, 125 h", "Workload: ~40 h Anwesenheit · ~50 h Hausübungen · ~35 h Testvorbereitung", "1. Antritt laut Syllabus: <b>4 Laboreingangstests</b> à 10 und <b>3 Hausübungen</b> à 10 (Nestler); keines muss separat positiv sein", "Moodle: schriftliche Prüfung als <b>Multiple Choice</b>, Punktebekanntgabe, Abgabe der Assignments · Noten über JOANNEUM|Online", "Assignments: am Ende einer Laborübung ausgegeben, Einzelarbeit, Dokumentation der Lösung; Abgabedatum wird bei Ausgabe festgelegt; <b>−1 Punkt pro Kalendertag</b> Verspätung (auch Sa/So)", "Mindestens <b>75 % Anwesenheit</b>; online nur mit aktivierter Kamera"] },
    { t: "html", html: "<table class='dt'><tr><th>Note</th><th>Punkte / %</th></tr><tr><td>1 · Sehr gut</td><td>91–100</td></tr><tr><td>2 · Gut</td><td>81–90</td></tr><tr><td>3 · Befriedigend</td><td>71–80</td></tr><tr><td>4 · Genügend</td><td>61–70</td></tr><tr><td>5 · Nicht genügend</td><td>0–60</td></tr></table><p>Nachkommastellen werden kaufmännisch gerundet (DIN 1333). 2./3. Antritt: Test (alle Teilbereiche) 50 + praktische Beispiele 50, <b>beide separat positiv</b>; 3. Antritt vor Prüfungskommission.</p>" },
    { t: "tip", html: "Für die Laboreingangstests: Übe im Exam Trainer die Fragen dieses Kurses und arbeite parallel den Microsoft-Learn-Lernpfad „Describe cloud concepts“ (AZ-900) durch." }
  ]}
 ]}
];

const QUESTIONS = [
 { id: "itgq1", topic: "itg-def", q: "Wie definiert die Folie Cloud Computing?", opts: ["Betrieb eigener Server im Keller", "Bereitstellung von Computing-Diensten über das Internet für schnellere Innovation, flexible Ressourcen und Economies of Scale", "Ein Mainframe mit Internetanschluss", "Software, die nur im Browser läuft"], a: 1, why: "Typische Dienste: Compute, Networking, Storage, Analytics.", ex: "" },
 { id: "itgq2", topic: "itg-def", q: "Aus welchen Bausteinen besteht das NIST-Cloud-Modell?", opts: ["3 Merkmale, 5 Service-Modelle, 4 Deployment-Modelle", "5 Merkmale, 3 Service-Modelle, 4 Deployment-Modelle", "4 Merkmale, 4 Service-Modelle, 3 Deployment-Modelle", "5 Merkmale, 4 Service-Modelle, 2 Deployment-Modelle"], a: 1, why: "NIST SP 800-145: 5 essential characteristics, 3 service models (IaaS, PaaS, SaaS), 4 deployment models.", ex: "" },
 { id: "itgq3", topic: "itg-def", q: "Welchen Wandel in der IT vergleicht die Folie mit dem Übergang von der Kutsche zum Auto?", opts: ["Von Mainframe zu Client/Server", "Von Client/Server (on-premises) zur Cloud", "Von Linux zu Windows", "Von Festplatte zu SSD"], a: 1, why: "Die Cloud verspricht nicht nur billigere, sondern auch schnellere, einfachere, flexiblere und effektivere IT.", ex: "" },
 { id: "itgq4", topic: "itg-nist", q: "Welches ist KEIN Essential Characteristic laut NIST?", opts: ["Resource pooling", "Rapid elasticity", "Pay-per-use contract", "Measured service"], a: 2, why: "Die fünf: On-demand self-service, Broad network access, Resource pooling, Rapid elasticity, Measured service.", ex: "" },
 { id: "itgq5", topic: "itg-nist", q: "Ein Entwickler legt um 23 Uhr über das Portal eine VM an, ohne mit dem Anbieter Kontakt aufzunehmen. Welches Merkmal?", opts: ["Broad network access", "On-demand self-service", "Measured service", "Resource pooling"], a: 1, why: "Bereitstellung einseitig, automatisch, ohne menschliche Interaktion mit dem Anbieter.", ex: "" },
 { id: "itgq6", topic: "itg-nist", q: "Welches NIST-Merkmal ermöglicht nutzungsbasierte Abrechnung und Transparenz für Anbieter und Kunde?", opts: ["Measured service", "Rapid elasticity", "Broad network access", "On-demand self-service"], a: 0, why: "Metering: Verbrauch wird gemessen, überwacht, gesteuert und berichtet.", ex: "" },
 { id: "itgq7", topic: "itg-nist", q: "„Multi-Tenant-Modell“ gehört zu welchem Merkmal?", opts: ["Rapid elasticity", "Measured service", "Resource pooling", "Broad network access"], a: 2, why: "Ressourcen des Anbieters werden gepoolt und vielen Konsumenten dynamisch zugeteilt.", ex: "" },
 { id: "itgq8", topic: "itg-deploy", q: "Welches Deployment-Modell existiert laut NIST immer in den Räumlichkeiten des Cloud-Anbieters?", opts: ["Private Cloud", "Community Cloud", "Public Cloud", "Hybrid Cloud"], a: 2, why: "Private und Community können on oder off premises liegen.", ex: "" },
 { id: "itgq9", topic: "itg-deploy", q: "Mehrere Behörden mit gleichen Sicherheits- und Compliance-Anforderungen nutzen gemeinsam eine exklusive Cloud. Deployment-Modell?", opts: ["Public Cloud", "Community Cloud", "Multi-Cloud", "Hybrid Cloud"], a: 1, why: "Gemeinschaft von Organisationen mit geteilten Anliegen (shared concerns).", ex: "" },
 { id: "itgq10", topic: "itg-deploy", q: "Was ist „Cloud Bursting“?", opts: ["Ein Totalausfall eines Rechenzentrums", "Lastspitzen werden aus der eigenen/privaten Cloud in eine Public Cloud ausgelagert", "Das Löschen aller Cloud-Ressourcen", "Eine Preisstrategie von Azure"], a: 1, why: "NIST-Beispiel für Hybrid Cloud: Load Balancing zwischen Clouds.", ex: "" },
 { id: "itgq11", topic: "itg-deploy", q: "Welche Herausforderung ist typisch für Multi-Cloud?", opts: ["Keine Verhandlungsmacht gegenüber Anbietern", "Unterschiedliche APIs/Tools, mehrere Skill-Sets, Egress-Kosten, komplexere Governance", "Zwingender Vendor Lock-in", "Nur ein Administrator nötig"], a: 1, why: "Motive sind dagegen Lock-in vermeiden, Best-of-Breed, Resilienz, Regulatorik, Verhandlungsmacht.", ex: "" },
 { id: "itgq13", topic: "itg-virt", q: "Welches Problem des Webshops beschreibt „Oversizing“?", opts: ["Server werden für die Spitzenlast ausgelegt, der Großteil der Kapazität bleibt ungenutzt", "Die Festplatte ist zu klein", "Der Shop hat zu viele Kunden", "Container sind zu groß"], a: 0, why: "Man zahlt für Leistung, die man meist nicht braucht.", ex: "" },
 { id: "itgq14", topic: "itg-virt", q: "Welcher Vorteil wird VMs auf der Folie zugeschrieben?", opts: ["Kein Betriebssystem nötig", "Standardisierung über Golden Images und einfaches Backup/Restore", "Scale to Zero", "Abrechnung pro Ausführung"], a: 1, why: "Außerdem: bessere Auslastung, Hardwareunabhängigkeit.", ex: "" },
 { id: "itgq15", topic: "itg-virt", q: "Was benötigt ein Container auf dem Host mindestens?", opts: ["Ein eigenes vollständiges Gastbetriebssystem", "Eine Container-Runtime auf dem Bare-Metal-Server oder in einer VM", "Einen Mainframe", "Eine eigene physische Netzwerkkarte"], a: 1, why: "Container packen nur Anwendung und Abhängigkeiten und nutzen das OS des Hosts.", ex: "" },
 { id: "itgq16", topic: "itg-virt", q: "Laut Kratzke war der Nachteil der Virtualisierung, den Container adressieren, …", opts: ["zu geringe Isolation", "sehr große VM-Images als Deployment Units", "fehlende Abrechnung", "zu wenige Rechenzentren"], a: 1, why: "Container starten schneller, sind kleiner und erhöhen die Anwendungsdichte pro VM.", ex: "" },
 { id: "itgq17", topic: "itg-faas", q: "Was bedeutet „Scale to Zero“ bei Serverless?", opts: ["Die Funktion wird gelöscht", "Ohne Last laufen keine Instanzen – und es wird nichts verrechnet", "Die Kosten sind immer null", "Es gibt keine Skalierung"], a: 1, why: "Löst das Leerlaufproblem aus Webshop | 1.", ex: "" },
 { id: "itgq18", topic: "itg-faas", q: "Wie wird Serverless typischerweise abgerechnet?", opts: ["Pro bereitgestelltem Server und Monat", "Pro Ausführung und Laufzeit, z. B. in GB-Sekunden", "Einmalige Lizenz", "Pro Mitarbeiter"], a: 1, why: "Nicht pro bereitgestelltem Server.", ex: "" },
 { id: "itgq19", topic: "itg-faas", q: "Welcher Dienst ist laut Folie KEIN Azure-Serverless-Beispiel?", opts: ["Azure Functions", "Azure Container Apps", "Azure Logic Apps", "Azure Virtual Machines"], a: 3, why: "VMs sind IaaS.", ex: "" },
 { id: "itgq20", topic: "itg-faas", q: "Für welche Workloads ist Serverless laut Folie ideal?", opts: ["Statische Dauerlast", "Periodische und unvorhersehbare Workloads (hohes p/a)", "Workloads ohne Code", "Nur Datenbanken"], a: 1, why: "Leerlauf kostet nichts, Spitzen werden automatisch bedient.", ex: "" },
 { id: "itgq21", topic: "itg-svc", q: "Bei welchem Service-Modell verwaltet der Anbieter die VMs inklusive Betriebssystem, während der Kunde seine Anwendung deployt?", opts: ["IaaS", "PaaS", "SaaS", "On-premises"], a: 1, why: "Managed Hosting Environment, z. B. Azure App Service.", ex: "" },
 { id: "itgq22", topic: "itg-svc", q: "Ein Unternehmen betreibt eine Azure-VM mit selbst installiertem SQL Server. Service-Modell?", opts: ["SaaS", "PaaS", "IaaS", "FaaS"], a: 2, why: "Kunde verwaltet OS und Datenbanksoftware.", ex: "" },
 { id: "itgq23", topic: "itg-svc", q: "Was muss der Kunde bei SaaS laut Folie im Wesentlichen nur noch bereitstellen?", opts: ["Hardware", "Betriebssystem", "Daten (und ggf. begrenzte Benutzereinstellungen)", "Runtime"], a: 2, why: "Der Anbieter verwaltet alle Aspekte der Anwendungsumgebung.", ex: "" },
 { id: "itgq24", topic: "itg-svc", q: "Welches Modell beschreibt die Folie als Kompromiss mit gewissem Lock-in, der aus der Plattform entsteht?", opts: ["IaaS", "PaaS", "SaaS", "Bare Metal"], a: 1, why: "Komfortabler Betrieb eigener Software, aber ressourceneffiziente Architektur und Lock-in akzeptieren.", ex: "" },
 { id: "itgq26", topic: "itg-shared", q: "Wofür ist der Kunde unabhängig vom Service-Modell IMMER verantwortlich?", opts: ["Physische Hosts", "Betriebssystem", "Informationen/Daten, Geräte, Konten und Identitäten", "Physisches Netzwerk"], a: 2, why: "Review-Frage 3.", ex: "" },
 { id: "itgq27", topic: "itg-shared", q: "Wofür ist der Anbieter IMMER verantwortlich?", opts: ["Datenklassifizierung", "Physisches Rechenzentrum, physisches Netzwerk, physische Hosts", "MFA-Einstellungen", "Endgeräte der Nutzer"], a: 1, why: "Alles Physische liegt immer beim Anbieter.", ex: "" },
 { id: "itgq28", topic: "itg-shared", q: "Wie verändern sich Lock-in und operative Komplexität von IaaS über PaaS zu SaaS?", opts: ["Lock-in sinkt, Komplexität steigt", "Lock-in steigt, Komplexität sinkt", "Beide steigen", "Beide sinken"], a: 1, why: "Ausgelagerter Anteil der Wertschöpfung wird größer.", ex: "" },
 { id: "itgq29", topic: "itg-shared", q: "Bei PaaS ist für die Runtime verantwortlich …", opts: ["der Kunde", "der Cloud-Anbieter", "der Endnutzer", "niemand"], a: 1, why: "Bei PaaS verwaltet der Kunde Anwendungen sowie Daten und Zugriff.", ex: "" },
 { id: "itgq30", topic: "itg-sla", q: "Wie viel Ausfallzeit pro Jahr erlaubt eine Verfügbarkeit von 99,99 %?", opts: ["5,26 Minuten", "52,6 Minuten", "8,76 Stunden", "3,65 Tage"], a: 1, why: "0,0001 × 525.600 min ≈ 52,6 min.", ex: "" },
 { id: "itgq31", topic: "itg-sla", q: "App Service (99,95 %) und SQL Database (99,99 %) werden beide benötigt. Composite SLA?", opts: ["99,99 %", "99,97 %", "99,94 %", "99,9999 %"], a: 2, why: "Seriell multiplizieren: 0,9995 × 0,9999 ≈ 0,9994 → ≈ 5,3 h/Jahr.", ex: "" },
 { id: "itgq32", topic: "itg-sla", q: "Zwei unabhängige Regionen mit je 99,95 % laufen redundant. Verfügbarkeit?", opts: ["99,90 %", "99,95 %", "≈ 99,99998 %", "100 %"], a: 2, why: "1 − 0,0005² = 0,99999975.", ex: "" },
 { id: "itgq34", topic: "itg-sla", q: "Einer VM mehr RAM und CPUs zuzuweisen ist …", opts: ["horizontale Skalierung", "vertikale Skalierung", "Elastizität per Spot", "Disaster Recovery"], a: 1, why: "Horizontal = mehr Instanzen.", ex: "" },
 { id: "itgq36", topic: "itg-scale", q: "Wie hoch können Hardwarerabatte großer Rechenzentrumsbetreiber laut Folie sein?", opts: ["bis zu 5 %", "bis zu 30 %", "bis zu 72 %", "bis zu 90 %"], a: 1, why: "Ermöglicht durch Infrastrukturhomogenität (Buying power).", ex: "" },
 { id: "itgq37", topic: "itg-scale", q: "Warum ist die Cloud laut Folie KEINE Rückkehr zur Mainframe-Ära?", opts: ["Weil Mainframes billiger sind", "Weil sie Skaleneffekte über dem Mainframe-Niveau mit Modularität und Agilität jenseits von Client/Server verbindet", "Weil sie keine Rechenzentren nutzt", "Weil sie nur SaaS anbietet"], a: 1, why: "Der Trade-off zwischen Effizienz und Flexibilität entfällt (Review-Frage 6).", ex: "" },
 { id: "itgq38", topic: "itg-scale", q: "Welcher Kostenfaktor wird laut Folie rasch zum größten Posten der TCO eines Rechenzentrums?", opts: ["Software-Lizenzen", "Stromkosten", "Mieten", "Marketing"], a: 1, why: "Große Anbieter: bessere PUE, Mengenrabatt, günstige Standorte.", ex: "" },
 { id: "itgq39", topic: "itg-workload", q: "Ein Startup kann nicht abschätzen, wie viele Nutzer nach einem Medienbericht kommen. Welches Workload-Muster?", opts: ["Time-of-day", "Uncertain growth („TechCrunch-Effekt“)", "Multi-resource", "Randomness"], a: 1, why: "Lange Vorlaufzeiten und Investitionsgenehmigung vor Kenntnis der Nachfrage.", ex: "" },
 { id: "itgq40", topic: "itg-workload", q: "Warum führt das Multi-resource-Muster zu ungenutzten Ressourcen?", opts: ["Weil Server als Bündel aus CPU, Storage und I/O gekauft werden, Workloads aber unterschiedliche Profile haben", "Weil Strom zu teuer ist", "Weil Nutzer zufällig zugreifen", "Weil Steuerfristen variieren"], a: 0, why: "Gegenmittel: Workloads mit komplementären Ressourcenprofilen kombinieren.", ex: "" },
 { id: "itgq41", topic: "itg-workload", q: "Welche Workload-Kategorie profitiert am stärksten von der Cloud?", opts: ["Static", "Continuously changing", "Periodic", "Unpredictable"], a: 3, why: "Pizza-Beispiel: bis zu 17,1-mal teurer darf der Anbieter sein.", ex: "" },
 { id: "itgq42", topic: "itg-pa", q: "Review-Frage 4: Peak 10 Server, Durchschnitt 2. Bis zu welchem Preisfaktor ist die Cloud noch günstiger?", opts: ["2", "5", "8", "20"], a: 1, why: "p/a = 10/2 = 5 → c < 5 · d.", ex: "" },
 { id: "itgq43", topic: "itg-pa", q: "Was bedeuten c und d in Weinmans Regel c/d < p/a?", opts: ["c = Kapazität, d = Bedarf", "c = Cloud-Kosten, d = In-house-Kosten", "c = CPU, d = Disk", "c = CapEx, d = Depreciation"], a: 1, why: "p = Peak, a = Average.", ex: "" },
 { id: "itgq44", topic: "itg-pa", q: "Wohnmobil: Kauf kostet ≈ 32 €/Tag, p/a ≈ 14,6. Welche Tagesmiete wäre maximal akzeptabel?", opts: ["≈ 32 €", "≈ 155 €", "≈ 467 €", "≈ 11.700 €"], a: 2, why: "32 € × 14,6 ≈ 467 €. Marktpreis 155 €/Tag → Mieten deutlich günstiger.", ex: "" },
 { id: "itgq45", topic: "itg-pa", q: "Bei einem perfekt statischen Workload (p/a = 1) lohnt sich die Cloud nur, wenn …", opts: ["sie pro Ressource billiger ist als in-house", "sie bis zu 17-mal teurer ist", "man Spot VMs nutzt", "immer"], a: 0, why: "c/d < 1 → c < d. Pizza „Static“: ≈ 1,4 wegen freier Wochenenden.", ex: "" },
 { id: "itgq47", topic: "itg-cost", q: "Welches Azure-Preismodell bietet laut Folie bis zu 72 % Rabatt gegenüber Pay-as-you-go?", opts: ["Spot VMs", "Reserved Instances (1 oder 3 Jahre)", "Azure Hybrid Benefit", "Savings Plan for Compute"], a: 1, why: "Savings Plan bis 65 %, Spot bis 90 % (verdrängbar).", ex: "" },
 { id: "itgq48", topic: "itg-cost", q: "CapEx wird betriebswirtschaftlich …", opts: ["sofort als Aufwand gebucht", "als Vermögenswert aktiviert und über die Nutzungsdauer (IT typ. 3–5 Jahre) abgeschrieben", "nie bilanziert", "nur bei SaaS verwendet"], a: 1, why: "OpEx = Aufwand der laufenden Periode.", ex: "" },
 { id: "itgq49", topic: "itg-cost", q: "Was ist KEINE typische Cloud-Kostenfalle laut Folie?", opts: ["Vergessene idle VMs und nicht angehängte Disks", "Egress-Gebühren", "Fehlende Tags und Budgets", "Automatisches Abschalten außerhalb der Geschäftszeiten"], a: 3, why: "Abschalten ist eine Gegenmaßnahme (Periodic-Workloads, FinOps).", ex: "" },
 { id: "itgq50", topic: "itg-cost", q: "Welche Kosten gehören laut Folie in eine TCO-Betrachtung?", opts: ["Nur Hardware", "Nur die monatliche Cloud-Rechnung", "Hardware, Lizenzen, Energie, Fläche, Kühlung, Personal, Ausfallzeiten, Migrations- und Exit-Kosten", "Nur Personal"], a: 2, why: "Total Cost of Ownership umfasst alle Kosten über den Lebenszyklus.", ex: "" },
 { id: "itgq52", topic: "itg-dist", q: "Welches ist eines der 8 Fallacies of Distributed Computing?", opts: ["Everything fails all the time", "Bandwidth is infinite", "Scale out, not up", "Focus on MTTR"], a: 1, why: "Die anderen drei sind Gebote der Cloud.", ex: "" },
 { id: "itgq53", topic: "itg-dist", q: "Was fordert das Gebot „Focus on MTTR, not MTTF“?", opts: ["Ausfälle um jeden Preis verhindern", "Schnelle Wiederherstellung nach Ausfällen statt Maximierung der Zeit bis zum Ausfall", "Mehr Hardware kaufen", "Nur Mainframes nutzen"], a: 1, why: "MTTR = Mean Time to Repair, MTTF = Mean Time to Failure.", ex: "" },
 { id: "itgq54", topic: "itg-dist", q: "Welcher Anbieter hatte laut Synergy Q1 2026 den größten Marktanteil an Cloud-Infrastruktur?", opts: ["Microsoft Azure", "Google Cloud", "Amazon (AWS)", "IONOS"], a: 2, why: "AWS 28 %, Azure 21 %, Google 14 % – zusammen 63 %.", ex: "" },
 { id: "itgq55", topic: "itg-dist", q: "Was nennt die Folie als Haupttreiber des Public-Cloud-Wachstums?", opts: ["E-Mail", "KI (Training und Inferenz)", "Mainframe-Migration", "Druckdienste"], a: 1, why: "Weitere: Hybrid/Multi-Cloud, Sovereign Cloud.", ex: "" },
 { id: "itgq56", topic: "itg-reg", q: "Was regelt DORA?", opts: ["Datenschutz für alle Bürger", "IKT-Risikomanagement im Finanzsektor inkl. Aufsicht über kritische IKT-Drittanbieter", "Wechsel zwischen Cloud-Anbietern", "US-Zugriff auf Daten"], a: 1, why: "Anwendbar seit Jänner 2025.", ex: "" },
 { id: "itgq57", topic: "itg-reg", q: "Was ermöglicht der US CLOUD Act (2018)?", opts: ["Kostenlose Cloud für Behörden", "US-Behörden können Daten von US-Anbietern verlangen, auch wenn sie in der EU gespeichert sind", "EU-Behörden können US-Daten verlangen", "Verbot von Rechenzentren in der EU"], a: 1, why: "Darum gilt: Data Residency ≠ Data Sovereignty.", ex: "" },
 { id: "itgq58", topic: "itg-reg", q: "Was ist der Unterschied zwischen Data Residency und Data Sovereignty?", opts: ["Kein Unterschied", "Residency = Speicherort; Sovereignty = welchem Recht die Daten unterliegen und wer Zugriff erzwingen kann", "Residency = Verschlüsselung; Sovereignty = Backup", "Residency gilt nur für SaaS"], a: 1, why: "Review-Frage 7. Beispiel: EU Data Boundary vs. CLOUD Act.", ex: "" },
 { id: "itgq59", topic: "itg-reg", q: "Wie berechnet sich die PUE?", opts: ["IT-Energie ÷ Gesamtenergie", "Gesamtenergie der Anlage ÷ Energie der IT-Geräte", "Stromkosten ÷ Umsatz", "kWh pro VM"], a: 1, why: "Große Anbieter erreichen ≈ 1,1.", ex: "" },
 { id: "itgq61", topic: "itg-azure", q: "Welche Reihenfolge der Azure-Hierarchie ist korrekt (von oben nach unten)?", opts: ["Resource Group → Subscription → Management Group → Resource", "Management Group → Subscription → Resource Group → Resource", "Subscription → Management Group → Resource → Resource Group", "Resource → Resource Group → Subscription → Management Group"], a: 1, why: "Grundwissen AZ-900.", ex: "" },
 { id: "itgq62", topic: "itg-azure", q: "Welcher Azure-Dienst stellt ein isoliertes privates Netzwerk mit Subnetzen bereit?", opts: ["Azure DNS", "Azure Virtual Network", "Azure Key Vault", "Azure Policy"], a: 1, why: "VNets werden laut Syllabus im Labor verwendet.", ex: "" },
 { id: "itgq63", topic: "itg-azure", q: "Laut Syllabus wird Azure DNS eingesetzt für …", opts: ["nur öffentliche Zonen", "öffentliche und private Zonen", "nur E-Mail", "Zertifikate"], a: 1, why: "Private Zonen lösen nur innerhalb verknüpfter VNets auf.", ex: "" },
 { id: "itgq64", topic: "itg-azid", q: "Was unterscheidet Azure Policy von RBAC?", opts: ["Kein Unterschied", "RBAC regelt, wer welche Aktionen ausführen darf; Policy regelt, welche Ressourcenzustände/-eigenschaften erlaubt sind", "Policy verwaltet Passwörter", "RBAC gilt nur on-premises"], a: 1, why: "Beide werden laut Syllabus behandelt (RBAC und zentrales Konfigurationsmanagement).", ex: "" },
 { id: "itgq65", topic: "itg-azid", q: "Was speichert Azure Key Vault?", opts: ["VM-Images", "Secrets, Schlüssel und Zertifikate", "Benutzerkonten", "DNS-Zonen"], a: 1, why: "Management von Schlüsseln und Geheimnissen laut Lernergebnissen.", ex: "" },
 { id: "itgq66", topic: "itg-azid", q: "Welche Kombination ist echte Multifaktorauthentifizierung?", opts: ["Passwort + Sicherheitsfrage", "Passwort + Code aus Authenticator-App am Handy", "Zwei verschiedene Passwörter", "Benutzername + Passwort"], a: 1, why: "Wissen + Besitz. Passwort und Sicherheitsfrage sind beide Wissen.", ex: "" },
 { id: "itgq67", topic: "itg-azid", q: "Wie heißt der cloudbasierte Verzeichnisdienst von Microsoft (früher Azure AD)?", opts: ["Microsoft Entra ID", "Azure Arc", "Azure Policy", "Active Directory Federation Mainframe"], a: 0, why: "Laut Syllabus zentrales Thema der LV.", ex: "" }
];

const BOSS_EXTRA = [
 { id: "itgq68", topic: "itg-sla", q: "Übung der Folie: Webshop mit App Service (99,95 %), SQL Database (99,99 %) und Storage (99,9 %), alle seriell. Composite SLA und Ausfall pro Jahr?", opts: ["99,9 % · 8,8 h", "≈ 99,84 % · ≈ 14 h", "≈ 99,95 % · ≈ 4,4 h", "≈ 99,61 % · ≈ 34 h"], a: 1, why: "0,9995 × 0,9999 × 0,999 ≈ 0,9984 → 0,0016 × 8.760 h ≈ 14 h." },
 { id: "itgq69", topic: "itg-pa", q: "Ein Batch-Job läuft an 6 Tagen im Monat (30 Tage) mit 20 Servern, sonst gar nicht. Die Cloud kostet pro Server-Tag das 4-Fache der eigenen Hardware. Entscheidung nach Weinman?", opts: ["On-prem, weil 4 > 1", "Cloud, weil c/d = 4 < p/a = 5", "Gleich teuer", "Cloud, weil p/a = 20"], a: 1, why: "p = 20, a = 20 × 6/30 = 4 → p/a = 5 > 4." },
 { id: "itgq70", topic: "itg-shared", q: "Ein Unternehmen nutzt nur SaaS (Microsoft 365). Ein Mitarbeiterkonto ohne MFA wird per Phishing übernommen. Wer trägt die Verantwortung?", opts: ["Microsoft, weil SaaS", "Der Kunde – Konten und Identitäten bleiben immer beim Kunden", "Niemand", "Der Internetprovider"], a: 1, why: "Shared Responsibility: Accounts/Identities, Daten und Geräte sind immer Kundenverantwortung." },
 { id: "itgq71", topic: "itg-cost", q: "Ein Webshop hat 4 Server Grundlast rund um die Uhr und zusätzlich unvorhersehbare Spitzen. Sinnvollster Preismodell-Mix?", opts: ["Alles Spot VMs", "Grundlast über Reserved Instances/Savings Plan, Spitzen per Autoscaling mit Pay-as-you-go bzw. Serverless", "Alles Reserved Instances für die Spitzenlast", "Nur Azure Hybrid Benefit"], a: 1, why: "Preismodell muss zum Workload passen: statischer Anteil → Commitment, unvorhersehbarer Anteil → flexibel." },
 { id: "itgq72", topic: "itg-faas", q: "Warum bleibt laut Folie der Kern-Shop meist in Containern oder PaaS und wird nur durch Functions ergänzt?", opts: ["Functions sind immer teurer", "Wegen Cold Starts, Laufzeitlimits, Plattform-Lock-in und schwierigerem Debugging", "Weil Functions kein HTTP können", "Weil Container Scale to Zero können"], a: 1, why: "Trade-offs von Serverless; Functions für event-getriebene Aufgaben und Lastspitzen." },
 { id: "itgq73", topic: "itg-deploy", q: "Ein Unternehmen nutzt sein eigenes Rechenzentrum und zusätzlich Azure und AWS. Wie ist das korrekt zu bezeichnen?", opts: ["Nur Hybrid Cloud", "Nur Multi-Cloud", "Hybrid und Multi-Cloud kombiniert", "Community Cloud"], a: 2, why: "On-prem + Public = Hybrid; zwei Public-Anbieter = Multi-Cloud – beides wird oft kombiniert." },
 { id: "itgq74", topic: "itg-reg", q: "Ein Unternehmen speichert Daten in der Microsoft EU Data Boundary. Welche Aussage passt zur Folie „Digitale Souveränität“?", opts: ["Damit ist US-Zugriff rechtlich ausgeschlossen", "Datenresidenz in EU/EFTA ist gegeben, aber Microsoft konnte unter Eid nicht garantieren, dass Daten nicht an ausländische Behörden gehen", "Die DSGVO verbietet die EU Data Boundary", "Die EU Data Boundary gilt nur für AWS"], a: 1, why: "Anhörung vor dem französischen Senat, Juni 2025." },
 { id: "itgq75", topic: "itg-dist", q: "Ein Team baut eine verteilte App und geht davon aus, dass Datentransfer zwischen Regionen nichts kostet. Welche Fallacy – und welche reale Cloud-Folge?", opts: ["Latency is zero – Cold Starts", "Transport cost is zero – Egress-Gebühren", "The network is secure – CLOUD Act", "Topology doesn't change – Spot-Eviction"], a: 1, why: "Egress ist ein typischer Kostentreiber und Lock-in-Faktor." },
 { id: "itgq76", topic: "itg-workload", q: "Welche Kombination glättet die Gesamtlast auf gemeinsam genutzten Servern am besten?", opts: ["Zwei Consumer-Apps mit Abendspitze", "Eine Consumer-App (abends) und eine Enterprise-App (tagsüber)", "Zwei CPU-lastige Suchdienste", "Zwei Steuer-Apps mit Spitze im April"], a: 1, why: "Komplementäre Time-of-day-Muster gleichen sich aus." }
];

