const MIX = (list) => list.map((q, i) => { const n = q.opts.length, target = i % n, shift = (target - q.a + n) % n;
  const opts = q.opts.map((_, k) => q.opts[(k - shift + n) % n]); return Object.assign({}, q, { opts: opts, a: target }); });

/* Same for the inline comprehension checks in the lessons. */
let ci = 0;
WORLDS.forEach(w => w.lessons.forEach(l => { l.blocks = l.blocks.map(b => {
  if (b.t !== "check") return b;
  const n = b.opts.length, target = (ci++ * 3 + 2) % n, shift = (target - b.a + n) % n;
  return Object.assign({}, b, { opts: b.opts.map((_, k) => b.opts[(k - shift + n) % n]), a: target });
}); }));

